-- CodeCart PRO: новые описания модулей (суть, возможности, как работает, кому подходит, демо) и meta description.
SET NAMES utf8mb4;
START TRANSACTION;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Order Email PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Order Email PRO&lt;/strong&gt; замінює або доповнює стандартні листи OpenCart/ocStore професійними HTML-листами для клієнта й адміністратора: нове замовлення, зміна статусу, реєстрація, повернення, звернення, ваучер, партнерська реєстрація та транзакції.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Листи для клієнта й адміністратора: замовлення, статуси, реєстрація, повернення, контактна форма, ваучер, партнерська реєстрація, транзакції&lt;/li&gt;&lt;li&gt;✅ Багатомовні шаблони та окремі листи для різних статусів замовлення&lt;/li&gt;&lt;li&gt;✅ Візуальний редактор і HTML-режим із синхронізацією правок&lt;/li&gt;&lt;li&gt;✅ Змінні замовлення, товари й підсумки, логотип і фірмові кольори&lt;/li&gt;&lt;li&gt;✅ Попередній перегляд і тестове надсилання до вмикання&lt;/li&gt;&lt;li&gt;✅ Резерв шаблонів: імпорт та експорт JSON, відновлення шаблону за замовчуванням&lt;/li&gt;&lt;li&gt;✅ Захист від дублів, журнал надсилання та розширена діагностика&lt;/li&gt;&lt;li&gt;✅ Ліцензійний ключ активується в розділі «Про модуль»&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Оберіть дизайн і налаштуйте логотип, кольори та тексти&lt;/li&gt;&lt;li&gt;2️⃣ Перевірте попередній перегляд і надішліть тестовий лист&lt;/li&gt;&lt;li&gt;3️⃣ Увімкніть модуль — клієнти почнуть отримувати нові листи&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Модуль встановлюється вимкненим.&lt;/li&gt;&lt;li&gt;✅ Перевірте шаблони на тестовому замовленні, щоб переконатися, що листи коректно виглядають у вашій пошті.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ HTML-листи&lt;/li&gt;&lt;li&gt;✅ UA / RU / EN&lt;/li&gt;&lt;li&gt;✅ Попередній перегляд&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Інтерфейс трьома мовами&lt;/h3&gt;&lt;p&gt;Адмінка модуля доступна російською, українською та англійською мовами — зручно для магазинів і команд, які працюють у різних мовних середовищах.&lt;/p&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Order Email PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Order Email PRO замінює або доповнює стандартні листи OpenCart/ocStore професійними HTML-листами для клієнта й адміністратора: нове замовлення, зміна…' WHERE `product_id`=51 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Order Email PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Order Email PRO&lt;/strong&gt; replaces or complements the standard OpenCart/ocStore e-mails with professional HTML e-mails for customers and administrators: new order, status change, registration, return, contact form, voucher, affiliate registration and transactions.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Customer and administrator e-mails: order, status, registration, return, contact form, voucher, affiliate registration, transactions&lt;/li&gt;&lt;li&gt;✅ Multilingual templates and separate e-mails for different order statuses&lt;/li&gt;&lt;li&gt;✅ A visual editor and an HTML mode with synchronized edits&lt;/li&gt;&lt;li&gt;✅ Order variables, products and totals, logo and brand colors&lt;/li&gt;&lt;li&gt;✅ Preview and test sending before you switch it on&lt;/li&gt;&lt;li&gt;✅ Template backup: JSON import and export, restoring the default template&lt;/li&gt;&lt;li&gt;✅ Duplicate protection, a send log and extended diagnostics&lt;/li&gt;&lt;li&gt;✅ License key activation in the About tab&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Choose a design and set the logo, colors and texts&lt;/li&gt;&lt;li&gt;2️⃣ Check the preview and send a test e-mail&lt;/li&gt;&lt;li&gt;3️⃣ Enable the module — customers start receiving the new e-mails&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ The module is installed switched off.&lt;/li&gt;&lt;li&gt;✅ Check the templates on a test order to confirm the e-mails look right in your mailbox.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ HTML e-mails&lt;/li&gt;&lt;li&gt;✅ UA / RU / EN&lt;/li&gt;&lt;li&gt;✅ Preview&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Three-language interface&lt;/h3&gt;&lt;p&gt;The module admin is available in Russian, Ukrainian and English — convenient for stores and teams working in different language environments.&lt;/p&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Order Email PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Order Email PRO replaces or complements the standard OpenCart/ocStore e-mails with professional HTML e-mails for customers and administrators: new order…' WHERE `product_id`=51 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Order Email PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Order Email PRO&lt;/strong&gt; заменяет или дополняет стандартные письма OpenCart/ocStore профессиональными HTML-письмами для клиента и администратора: новый заказ, смена статуса, регистрация, возврат, обращения, ваучер, партнёрская регистрация и транзакции.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Письма для клиента и администратора: заказ, статусы, регистрация, возврат, контактная форма, ваучер, партнёрская регистрация, транзакции&lt;/li&gt;&lt;li&gt;✅ Многоязычные шаблоны и отдельные письма для разных статусов заказа&lt;/li&gt;&lt;li&gt;✅ Визуальный редактор и HTML-режим с синхронизацией правок&lt;/li&gt;&lt;li&gt;✅ Переменные заказа, товары и итоги, логотип и фирменные цвета&lt;/li&gt;&lt;li&gt;✅ Предпросмотр и тестовая отправка до включения&lt;/li&gt;&lt;li&gt;✅ Резерв шаблонов: импорт и экспорт JSON, восстановление шаблона по умолчанию&lt;/li&gt;&lt;li&gt;✅ Защита от дублей, журнал отправки и расширенная диагностика&lt;/li&gt;&lt;li&gt;✅ Лицензионный ключ активируется в разделе «О модуле»&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Выберите дизайн и настройте логотип, цвета и тексты&lt;/li&gt;&lt;li&gt;2️⃣ Проверьте предпросмотр и отправьте тестовое письмо&lt;/li&gt;&lt;li&gt;3️⃣ Включите модуль — клиенты начнут получать новые письма&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Модуль устанавливается выключенным.&lt;/li&gt;&lt;li&gt;✅ Проверьте шаблоны на тестовом заказе, чтобы убедиться, что письма корректно выглядят в вашей почте.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ HTML-письма&lt;/li&gt;&lt;li&gt;✅ UA / RU / EN&lt;/li&gt;&lt;li&gt;✅ Предпросмотр&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Интерфейс на трёх языках&lt;/h3&gt;&lt;p&gt;Админка модуля доступна на русском, украинском и английском языках — удобно для магазинов и команд, работающих в разных языковых средах.&lt;/p&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Order Email PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Order Email PRO заменяет или дополняет стандартные письма OpenCart/ocStore профессиональными HTML-письмами для клиента и администратора: новый заказ, смена…' WHERE `product_id`=51 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;UTF8MB4 Converter PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;UTF8MB4 Converter PRO&lt;/strong&gt; перевіряє базу магазину та безпечно переводить її зі старого utf8/utf8mb3 на utf8mb4.&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Так у тексті, назвах і відгуках коректно зберігаються емодзі та рідкісні символи, а таблиці приводяться до сучасного рушія InnoDB.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Діагностика кодування бази, таблиць, колонок і поточного підключення&lt;/li&gt;&lt;li&gt;✅ Перевірка версії MySQL/MariaDB, collation і рушіїв таблиць&lt;/li&gt;&lt;li&gt;✅ Пакетна черга конвертації: пауза, продовження, зупинка, прогрес&lt;/li&gt;&lt;li&gt;✅ Переведення таблиць в InnoDB — окремою дією з підтвердженням&lt;/li&gt;&lt;li&gt;✅ Контроль нових таблиць, що з’явилися після встановлення сторонніх розширень&lt;/li&gt;&lt;li&gt;✅ Перевірка language-файлів на BOM, битий UTF-8, керівні та приховані символи&lt;/li&gt;&lt;li&gt;✅ Оборотний OCMOD підключення до бази через utf8mb4 без правки файлів ядра&lt;/li&gt;&lt;li&gt;✅ Таблиці інших проєктів у тій самій базі показуються окремо й не змінюються&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Запустіть діагностику й вивчіть звіт&lt;/li&gt;&lt;li&gt;2️⃣ Зробіть резервну копію та запустіть чергу конвертації&lt;/li&gt;&lt;li&gt;3️⃣ Переведіть таблиці в InnoDB і перевірте language-файли&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ ALTER TABLE може блокувати запис — виконуйте в період низького навантаження.&lt;/li&gt;&lt;li&gt;✅ Уже зіпсовані символи (знаки питання) автоматично не відновити.&lt;/li&gt;&lt;li&gt;✅ Модуль вимкнений після встановлення.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ utf8mb4&lt;/li&gt;&lt;li&gt;✅ InnoDB&lt;/li&gt;&lt;li&gt;✅ MySQL · MariaDB&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Інтерфейс трьома мовами&lt;/h3&gt;&lt;p&gt;Адмінка модуля доступна російською, українською та англійською мовами — зручно для магазинів і команд, які працюють у різних мовних середовищах.&lt;/p&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;UTF8MB4 Converter PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де пр