UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Google Reviews PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Google Reviews PRO&lt;/strong&gt; підключає офіційний механізм Google Customer Reviews: після завершеного замовлення покупцеві пропонують залишити відгук про магазин, а рейтинг Google зміцнює довіру.&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Відгук збирає сам Google у реального покупця — модуль його не створює.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Офіційний opt-in Google Customer Reviews на сторінці успішного замовлення&lt;/li&gt;&lt;li&gt;✅ Передача даних замовлення та Merchant ID у форматі, якого очікує Google&lt;/li&gt;&lt;li&gt;✅ Елементи рейтингу магазину (значок, кількість відгуків) в адаптивному блоці вітрини&lt;/li&gt;&lt;li&gt;✅ Керування місцем і виглядом відображення блоку&lt;/li&gt;&lt;li&gt;✅ Кешування даних рейтингу, щоб не навантажувати вітрину&lt;/li&gt;&lt;li&gt;✅ Перевірка налаштувань перед увімкненням&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Вкажіть Merchant ID із Google Merchant Center&lt;/li&gt;&lt;li&gt;2️⃣ Оберіть, де показувати блок рейтингу&lt;/li&gt;&lt;li&gt;3️⃣ Увімкніть модуль і оформіть тестове замовлення&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Потрібен коректний Merchant ID і відповідність вимогам програми Google.&lt;/li&gt;&lt;li&gt;✅ Модуль нічого не пише за покупця.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Google Customer Reviews&lt;/li&gt;&lt;li&gt;✅ Merchant Center&lt;/li&gt;&lt;li&gt;✅ Рейтинг&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Google Reviews PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Google Reviews PRO підключає офіційний механізм Google Customer Reviews: після завершеного замовлення покупцеві пропонують залишити відгук про магазин, а…' WHERE `product_id`=71 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Google Reviews PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Google Reviews PRO&lt;/strong&gt; connects the official Google Customer Reviews flow: after a completed order the buyer is invited to review the store, and the Google rating builds trust.&lt;/p&gt;&lt;h3&gt;💡 Why you need it&lt;/h3&gt;&lt;p&gt;Google collects the review from a real buyer — the module never writes one.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Official Google Customer Reviews opt-in on the order-success page&lt;/li&gt;&lt;li&gt;✅ Order data and Merchant ID passed in the format Google expects&lt;/li&gt;&lt;li&gt;✅ Store-rating elements (badge, review count) in a responsive storefront block&lt;/li&gt;&lt;li&gt;✅ Control over where and how the block is shown&lt;/li&gt;&lt;li&gt;✅ Rating data caching so the storefront is not slowed down&lt;/li&gt;&lt;li&gt;✅ Settings check before enabling&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Enter your Merchant ID from Google Merchant Center&lt;/li&gt;&lt;li&gt;2️⃣ Choose where to show the rating block&lt;/li&gt;&lt;li&gt;3️⃣ Enable the module and place a test order&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ A valid Merchant ID and compliance with Google’s program rules are required.&lt;/li&gt;&lt;li&gt;✅ The module never writes anything on behalf of the buyer.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Google Customer Reviews&lt;/li&gt;&lt;li&gt;✅ Merchant Center&lt;/li&gt;&lt;li&gt;✅ Rating&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Google Reviews PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Google Reviews PRO connects the official Google Customer Reviews flow: after a completed order the buyer is invited to review the store, and the Google…' WHERE `product_id`=71 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Google Reviews PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Google Reviews PRO&lt;/strong&gt; подключает официальный механизм Google Customer Reviews: после завершённого заказа покупателю предлагают оставить отзыв о магазине, а рейтинг Google укрепляет доверие.&lt;/p&gt;&lt;h3&gt;💡 Зачем нужен модуль&lt;/h3&gt;&lt;p&gt;Отзыв собирает сам Google у реального покупателя — модуль его не создаёт.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Официальный opt-in Google Customer Reviews на странице успешного заказа&lt;/li&gt;&lt;li&gt;✅ Передача данных заказа и Merchant ID в формате, который ждёт Google&lt;/li&gt;&lt;li&gt;✅ Элементы рейтинга магазина (значок, количество отзывов) в адаптивном блоке витрины&lt;/li&gt;&lt;li&gt;✅ Управление местом и видом отображения блока&lt;/li&gt;&lt;li&gt;✅ Кеширование данных рейтинга, чтобы не нагружать витрину&lt;/li&gt;&lt;li&gt;✅ Проверка настроек перед включением&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Укажите Merchant ID из Google Merchant Center&lt;/li&gt;&lt;li&gt;2️⃣ Выберите, где показывать блок рейтинга&lt;/li&gt;&lt;li&gt;3️⃣ Включите модуль и оформите тестовый заказ&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Нужен корректный Merchant ID и соответствие требованиям программы Google.&lt;/li&gt;&lt;li&gt;✅ Модуль ничего не пишет за покупателя.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Google Customer Reviews&lt;/li&gt;&lt;li&gt;✅ Merchant Center&lt;/li&gt;&lt;li&gt;✅ Рейтинг&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Google Reviews PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Google Reviews PRO подключает официальный механизм Google Customer Reviews: после завершённого заказа покупателю предлагают оставить отзыв о магазине, а…' WHERE `product_id`=71 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Nova Poshta PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Nova Poshta PRO&lt;/strong&gt; додає в OpenCart/ocStore доставку Новою Поштою: вибір міста, відділення, поштомата чи адресної доставки в checkout, збереження даних у замовленні, створення ТТН та оновлення її статусів.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Покупець обирає реальне місто та відділення Нової Пошти просто під час оформлення замовлення&lt;/li&gt;&lt;li&gt;✅ Відділення, поштомат або адресна доставка; дані зберігаються в замовленні й не губляться після оформлення&lt;/li&gt;&lt;li&gt;✅ Блок Нової Пошти на сторінці замовлення в адмінці; створення ТТН із замовлення та список ТТН&lt;/li&gt;&lt;li&gt;✅ Оновлення статусів ТТН та email-сповіщення&lt;/li&gt;&lt;li&gt;✅ Довідники міст, відділень і вулиць оновлюються вручну або через cron&lt;/li&gt;&lt;li&gt;✅ Дані відправника завантажуються з кабінету; перевірка API однією кнопкою&lt;/li&gt;&lt;li&gt;✅ Налаштування видимості стандартних адресних полів для кожного активного способу доставки&lt;/li&gt;&lt;li&gt;✅ Безпечна конфігурація checkout, маскування ключів у журналі API, повтор при тимчасових помилках сервісу; сумісність з UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Введіть API-ключ Нової Пошти та завантажте дані відправника&lt;/li&gt;&lt;li&gt;2️⃣ Завантажте довідники й налаштуйте cron&lt;/li&gt;&lt;li&gt;3️⃣ Увімкніть спосіб доставки й перевірте тестове замовлення&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Потрібен API-ключ з кабінету Нової Пошти.&lt;/li&gt;&lt;li&gt;✅ Після встановлення модуль вимкнений і не впливає на вітрину, доки ви не ввімкнете його й не збережете налаштування.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ API Нової Пошти&lt;/li&gt;&lt;li&gt;✅ Cron довідників&lt;/li&gt;&lt;li&gt;✅ Створення ТТН&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Nova Poshta PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Nova Poshta PRO додає в OpenCart/ocStore доставку Новою Поштою: вибір міста, відділення, поштомата чи адресної доставки в checkout, збереження даних у…' WHERE `product_id`=72 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Nova Poshta PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Nova Poshta PRO&lt;/strong&gt; adds Nova Poshta delivery to OpenCart/ocStore: city, warehouse, postomat or address delivery selection at checkout, delivery data saved in the order, TTN creation and status updates.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Customers pick a real Nova Poshta city and warehouse during checkout&lt;/li&gt;&lt;li&gt;✅ Warehouse, postomat or address delivery; the data is saved with the order and not lost after checkout&lt;/li&gt;&lt;li&gt;✅ A Nova Poshta block on the admin order page; TTN creation from the order and a TTN list&lt;/li&gt;&lt;li&gt;✅ TTN status updates and e-mail notifications&lt;/li&gt;&lt;li&gt;✅ City, warehouse and street directories updated manually or by cron&lt;/li&gt;&lt;li&gt;✅ Sender data is loaded from your account; one-click API check&lt;/li&gt;&lt;li&gt;✅ Standard address field visibility configurable per active shipping method&lt;/li&gt;&lt;li&gt;✅ Safe checkout configuration, masked keys in the API log, retries on transient service errors; UniShop2 compatible&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Enter the Nova Poshta API key and load the sender data&lt;/li&gt;&lt;li&gt;2️⃣ Load the directories and set up cron&lt;/li&gt;&lt;li&gt;3️⃣ Enable the shipping method and test with an order&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ An API key from your Nova Poshta account is required.&lt;/li&gt;&lt;li&gt;✅ After installation the module is off and does not affect the storefront until you enable it and save the settings.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Nova Poshta API&lt;/li&gt;&lt;li&gt;✅ Directory cron&lt;/li&gt;&lt;li&gt;✅ TTN creation&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Three-language interface&lt;/h3&gt;&lt;p&gt;The module admin is available in Russian, Ukrainian and English — convenient for stores and teams working in different language environments.&lt;/p&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Nova Poshta PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Nova Poshta PRO adds Nova Poshta delivery to OpenCart/ocStore: city, warehouse, postomat or address delivery selection at checkout, delivery data saved in…' WHERE `product_id`=72 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Nova Poshta PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Nova Poshta PRO&lt;/strong&gt; добавляет в OpenCart/ocStore доставку Новой Почтой: выбор города, отделения, почтомата или адресной доставки в checkout, сохранение данных в заказе, создание ТТН и обновление её статусов.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Покупатель выбирает реальный город и отделение Новой Почты прямо при оформлении заказа&lt;/li&gt;&lt;li&gt;✅ Отделение, почтомат или адресная доставка; данные сохраняются в заказе и не теряются после оформления&lt;/li&gt;&lt;li&gt;✅ Блок Новой Почты на странице заказа в админке; создание ТТН из заказа и список ТТН&lt;/li&gt;&lt;li&gt;✅ Обновление статусов ТТН и email-уведомления&lt;/li&gt;&lt;li&gt;✅ Справочники городов, отделений и улиц обновляются вручную или через cron&lt;/li&gt;&lt;li&gt;✅ Данные отправителя загружаются из кабинета; проверка API одной кнопкой&lt;/li&gt;&lt;li&gt;✅ Настройка видимости стандартных адресных полей для каждого активного способа доставки&lt;/li&gt;&lt;li&gt;✅ Безопасная конфигурация checkout, маскирование ключей в журнале API, повтор при временных ошибках сервиса; совместимость с UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Введите API-ключ Новой Почты и загрузите данные отправителя&lt;/li&gt;&lt;li&gt;2️⃣ Загрузите справочники и настройте cron&lt;/li&gt;&lt;li&gt;3️⃣ Включите способ доставки и проверьте тестовый заказ&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Нужен API-ключ из кабинета Новой Почты.&lt;/li&gt;&lt;li&gt;✅ После установки модуль отключён и не влияет на витрину, пока вы не включите его и не сохраните настройки.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ API Новой Почты&lt;/li&gt;&lt;li&gt;✅ Cron справочников&lt;/li&gt;&lt;li&gt;✅ Создание ТТН&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Nova Poshta PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Nova Poshta PRO добавляет в OpenCart/ocStore доставку Новой Почтой: выбор города, отделения, почтомата или адресной доставки в checkout, сохранение данных в…' WHERE `product_id`=72 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Import Export PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Import Export Pro&lt;/strong&gt; — модуль імпорту, експорту та синхронізації товарів для ocStore 3.0.4.1 і OpenCart 3.x: CSV, XLSX, XML/YML, JSON та HTML-таблиці, профілі постачальників, націнки, зображення й захищені публічні фіди.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Формати: CSV, XLSX, XML/YML, JSON, HTML-таблиці; файл або URL постачальника&lt;/li&gt;&lt;li&gt;✅ Режими запуску: повний імпорт, лише ціни, лише залишки, ціни й залишки, лише нові, лише наявні — обмеження виконуються на сервері&lt;/li&gt;&lt;li&gt;✅ Для кожного поля своя політика: не чіпати, перезаписати, заповнити лише порожнє, додати, замінити або очистити&lt;/li&gt;&lt;li&gt;✅ Профілі постачальників із картою полів, правилами, категоріями й націнками&lt;/li&gt;&lt;li&gt;✅ Тестовий імпорт без запису та пробний запуск на 10 рядків із попереднім переглядом&lt;/li&gt;&lt;li&gt;✅ Експорт, захищені публічні фіди та вивантаження для маркетплейсів&lt;/li&gt;&lt;li&gt;✅ Cron із захисним токеном, журнал операцій, діагностика&lt;/li&gt;&lt;li&gt;✅ Відсутня колонка ніколи не очищає дані; небезпечні очищення ключів блокуються&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Створіть профіль: джерело, карта полів і правила&lt;/li&gt;&lt;li&gt;2️⃣ Запустіть «Тест 10 рядків» або тестовий імпорт без запису й перевірте результат&lt;/li&gt;&lt;li&gt;3️⃣ Запустіть імпорт вручну або за cron; стежте за журналом&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Після встановлення й оновлення модуль вимкнений.&lt;/li&gt;&lt;li&gt;✅ Перший імпорт робіть на тестовій копії та обов’язково зробіть резервну копію бази.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновлен