UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Google Product Category Field PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Google Product Category Field PRO&lt;/strong&gt; добавляет в категорию OpenCart отдельное числовое поле Google Product Category ID для фидов и Merchant Center.&lt;/p&gt;&lt;h3&gt;💡 Зачем нужен модуль&lt;/h3&gt;&lt;p&gt;Это не SEO-поле и не внутренний category_id — отдельное поле не даёт их перепутать.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Поле Google Product Category ID в «Каталог → Категории → Данные»&lt;/li&gt;&lt;li&gt;✅ Хранится только числовой ID таксономии Google&lt;/li&gt;&lt;li&gt;✅ Значение используют фиды товаров (например, Merchant Feed Simple XML PRO)&lt;/li&gt;&lt;li&gt;✅ Наследование от родителя выполняет товарный фид&lt;/li&gt;&lt;li&gt;✅ Не затрагивает витрину и SEO&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Установите и включите модуль&lt;/li&gt;&lt;li&gt;2️⃣ Откройте категорию, вкладка «Данные»&lt;/li&gt;&lt;li&gt;3️⃣ Впишите числовой ID из таксономии Google и сохраните&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Сохраняйте только числовой ID, а не текстовый путь категории Google.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Google Merchant&lt;/li&gt;&lt;li&gt;✅ Категории&lt;/li&gt;&lt;li&gt;✅ ID таксономии&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Google Product Category Field PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Google Product Category Field PRO добавляет в категорию OpenCart отдельное числовое поле Google Product Category ID для фидов и Merchant Center. Это не…' WHERE `product_id`=90 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;AI Ready PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;AI Ready PRO&lt;/strong&gt; робить каталог OpenCart доступним для AI-асистентів і пошукових систем: створює llms.txt, AI Sitemap, фіди товарів, надсилає зміни через IndexNow та відкриває read-only MCP/WebMCP для публічного пошуку й читання.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ llms.txt і llms-full з окремими контентними файлами; у модулі прямо сказано, що llms.txt — не фактор ранжування Google&lt;/li&gt;&lt;li&gt;✅ AI Sitemap Index з автоматичним поділом великих каталогів, без ігнорованих Google priority/changefreq і без вигаданого lastmod&lt;/li&gt;&lt;li&gt;✅ Read-only MCP і WebMCP для публічних сценаріїв пошуку та читання каталогу&lt;/li&gt;&lt;li&gt;✅ OpenAI-compatible Product Feed у варіантах Core та Extended — із варіантами товарів і зображеннями&lt;/li&gt;&lt;li&gt;✅ IndexNow: постійна черга, пакетне надсилання, повтори з backoff&lt;/li&gt;&lt;li&gt;✅ Google UCP Cart transfer без оголошення непідтримуваних функцій checkout, оплати й замовлень&lt;/li&gt;&lt;li&gt;✅ Пріоритет контенту, попередній перегляд, тестова генерація без запису файлів, пакетна генерація та cron&lt;/li&gt;&lt;li&gt;✅ Діагностика robots.txt, пошукових і AI-краулерів, endpoints, джерел контенту, .htaccess, черг і файлів&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Увімкніть потрібні розділи та застосуйте профіль&lt;/li&gt;&lt;li&gt;2️⃣ Згенеруйте файли й перевірте попередній перегляд і діагностику&lt;/li&gt;&lt;li&gt;3️⃣ Налаштуйте cron та IndexNow, за потреби увімкніть WebMCP&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Модуль публікує лише публічні дані каталогу й не розкриває персональні дані.&lt;/li&gt;&lt;li&gt;✅ Перевірте robots.txt і endpoints у розділі діагностики.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ llms.txt · AI Sitemap&lt;/li&gt;&lt;li&gt;✅ MCP · WebMCP&lt;/li&gt;&lt;li&gt;✅ IndexNow&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;AI Ready PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='AI Ready PRO робить каталог OpenCart доступним для AI-асистентів і пошукових систем: створює llms.txt, AI Sitemap, фіди товарів, надсилає зміни через…' WHERE `product_id`=91 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;AI Ready PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;AI Ready PRO&lt;/strong&gt; makes an OpenCart catalog readable for AI assistants and search engines: it generates llms.txt, an AI Sitemap and product feeds, pushes changes through IndexNow and exposes a read-only MCP/WebMCP for public search and reading.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ llms.txt and llms-full with separate content files; the module states plainly that llms.txt is not a Google ranking factor&lt;/li&gt;&lt;li&gt;✅ AI Sitemap Index with automatic splitting of large catalogs, without Google-ignored priority/changefreq and without a fake lastmod&lt;/li&gt;&lt;li&gt;✅ Read-only MCP and WebMCP for public catalog search and read scenarios&lt;/li&gt;&lt;li&gt;✅ OpenAI-compatible Product Feed in Core and Extended variants — with product variants and images&lt;/li&gt;&lt;li&gt;✅ IndexNow: a persistent queue, batch submission, retries with backoff&lt;/li&gt;&lt;li&gt;✅ Google UCP Cart transfer without advertising unsupported checkout, payment or order features&lt;/li&gt;&lt;li&gt;✅ Content priority, preview, test generation without writing files, batch generation and cron&lt;/li&gt;&lt;li&gt;✅ Diagnostics for robots.txt, search and AI crawlers, endpoints, content sources, .htaccess, queues and files&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Enable the sections you need and apply a profile&lt;/li&gt;&lt;li&gt;2️⃣ Generate the files and check the preview and diagnostics&lt;/li&gt;&lt;li&gt;3️⃣ Set up cron and IndexNow, and enable WebMCP if needed&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ The module publishes only public catalog data and exposes no personal data.&lt;/li&gt;&lt;li&gt;✅ Check robots.txt and endpoints in the diagnostics section.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ llms.txt · AI Sitemap&lt;/li&gt;&lt;li&gt;✅ MCP · WebMCP&lt;/li&gt;&lt;li&gt;✅ IndexNow&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;AI Ready PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='AI Ready PRO makes an OpenCart catalog readable for AI assistants and search engines: it generates llms.txt, an AI Sitemap and product feeds, pushes changes…' WHERE `product_id`=91 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;AI Ready PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;AI Ready PRO&lt;/strong&gt; делает каталог OpenCart доступным для AI-ассистентов и поисковых систем: создаёт llms.txt, AI Sitemap, фиды товаров, отправляет изменения через IndexNow и открывает read-only MCP/WebMCP для публичного поиска и чтения.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ llms.txt и llms-full с отдельными контентными файлами; в модуле прямо сказано, что llms.txt — не фактор ранжирования Google&lt;/li&gt;&lt;li&gt;✅ AI Sitemap Index с автоматическим делением больших каталогов, без игнорируемых Google priority/changefreq и без выдуманного lastmod&lt;/li&gt;&lt;li&gt;✅ Read-only MCP и WebMCP для публичных сценариев поиска и чтения каталога&lt;/li&gt;&lt;li&gt;✅ OpenAI-compatible Product Feed в вариантах Core и Extended — с вариантами товаров и изображениями&lt;/li&gt;&lt;li&gt;✅ IndexNow: постоянная очередь, пакетная отправка, повторы с backoff&lt;/li&gt;&lt;li&gt;✅ Google UCP Cart transfer без объявления неподдерживаемых функций checkout, оплаты и заказов&lt;/li&gt;&lt;li&gt;✅ Приоритет контента, предпросмотр, тестовая генерация без записи файлов, пакетная генерация и cron&lt;/li&gt;&lt;li&gt;✅ Диагностика robots.txt, поисковых и AI-краулеров, endpoints, источников контента, .htaccess, очередей и файлов&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Включите нужные разделы и примените профиль&lt;/li&gt;&lt;li&gt;2️⃣ Сгенерируйте файлы и проверьте предпросмотр и диагностику&lt;/li&gt;&lt;li&gt;3️⃣ Настройте cron и IndexNow, при необходимости включите WebMCP&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Модуль публикует только публичные данные каталога и не раскрывает персональные данные.&lt;/li&gt;&lt;li&gt;✅ Проверьте robots.txt и endpoints в разделе диагностики.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ llms.txt · AI Sitemap&lt;/li&gt;&lt;li&gt;✅ MCP · WebMCP&lt;/li&gt;&lt;li&gt;✅ IndexNow&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;AI Ready PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='AI Ready PRO делает каталог OpenCart доступным для AI-ассистентов и поисковых систем: создаёт llms.txt, AI Sitemap, фиды товаров, отправляет изменения через…' WHERE `product_id`=91 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;OpenCart Theme PRO&lt;/strong&gt; — комерційна тема CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;OpenCart Theme PRO&lt;/strong&gt; — самостійна комерційна тема-вітрина для OpenCart/ocStore 3.x: адаптивний каталог, сучасні картки товарів, навігація, промо-блоки та набір вбудованих інструментів — від SEO-розмітки до налаштування вигляду.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Адаптивна вітрина: каталог, картки товарів, галерея, навігація&lt;/li&gt;&lt;li&gt;✅ Розширена schema.org-розмітка товару: brand, sku/mpn/gtin, зображення, priceValidUntil, aggregateRating, відгуки, shippingDetails і політика повернення — за наявності даних&lt;/li&gt;&lt;li&gt;✅ Захист категорій від дублів із параметрами sort, order, limit, filter, page (noindex,follow для технічних URL)&lt;/li&gt;&lt;li&gt;✅ Необов’язковий canonical на чисту категорію&lt;/li&gt;&lt;li&gt;✅ Фонове зображення сайту через менеджер зображень OpenCart&lt;/li&gt;&lt;li&gt;✅ Промо-блоки й налаштування оформлення з адмінки&lt;/li&gt;&lt;li&gt;✅ Блог і відгуки у складі рішення&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Встановіть тему й оновіть модифікатори&lt;/li&gt;&lt;li&gt;2️⃣ Налаштуйте кольори, блоки та розмітку в адмінці&lt;/li&gt;&lt;li&gt;3️⃣ Перевірте вітрину на мобільних пристроях і швидкість&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Тема зачіпає майже всю вітрину — перевіряйте сумісність з іншими модулями.&lt;/li&gt;&lt;li&gt;✅ Canonical вмикайте, лише якщо SEO-модуль не виводить свій.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Адаптивна тема&lt;/li&gt;&lt;li&gt;✅ schema.org&lt;/li&gt;&lt;li&gt;✅ OpenCart 3.x&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;OpenCart Theme PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='OpenCart Theme PRO — самостійна комерційна тема-вітрина для OpenCart/ocStore 3.x: адаптивний каталог, сучасні картки товарів, навігація, промо-блоки та набір…' WHERE `product_id`=92 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;OpenCart Theme PRO&lt;/strong&gt; is a commercial CodeCart PRO theme for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;OpenCart Theme PRO&lt;/strong&gt; is a standalone commercial storefront theme for OpenCart/ocStore 3.x: responsive catalog, modern product cards, navigation, promo blocks and built-in tools from SEO markup to appearance settings.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Responsive storefront: catalog, product cards, gallery, navigation&lt;/li&gt;&lt;li&gt;✅ Extended product schema.org: brand, sku/mpn/gtin, images, priceValidUntil, aggregateRating, reviews, shippingDetails and return policy when data exists&lt;/li&gt;&lt;li&gt;✅ Category duplicate protection for sort, order, limit, filter, page parameters (noindex,follow for technical URLs)&lt;/li&gt;&lt;li&gt;✅ Optional canonical to the clean category&lt;/li&gt;&lt;li&gt;✅ Site background image via the OpenCart image manager&lt;/li&gt;&lt;li&gt;✅ Promo blocks and appearance settings from the admin&lt;/li&gt;&lt;li&gt;✅ Blog and reviews included&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Install the theme and refresh modifications&lt;/li&gt;&lt;li&gt;2️⃣ Set colors, blocks and markup in the admin&lt;/li&gt;&lt;li&gt;3️⃣ Check the storefront on mobile and its speed&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ A theme affects almost the whole storefront — check compatibility with other modules.&lt;/li&gt;&lt;li&gt;✅ Enable canonical only if your SEO module does not output its own.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Responsive theme&lt;/li&gt;&lt;li&gt;✅ schema.org&lt;/li&gt;&lt;li&gt;✅ OpenCart 3.x&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;OpenCart Theme PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='OpenCart Theme PRO is a standalone commercial storefront theme for OpenCart/ocStore 3.x: responsive catalog, modern product cards, navigation, promo blocks…' WHERE `product_id`=92 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;OpenCart Theme PRO&lt;/strong&gt; — коммерческая тема CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;OpenCart Theme PRO&lt;/strong&gt; — самостоятельная коммерческая тема-витрина для OpenCart/ocStore 3.x: адаптивный каталог, современные карточки товаров, навигация, промо-блоки и набор встроенных инструментов, от SEO-разметки до настройки внешнего вида.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Адаптивная витрина: каталог, карточки товаров, галерея, навигация&lt;/li&gt;&lt;li&gt;✅ Расширенная schema.org-разметка товара: brand, sku/mpn/gtin, изображения, priceValidUntil, aggregateRating, отзывы, shippingDetails и политика возврата — при наличии данных&lt;/li&gt;&lt;li&gt;✅ Защита категорий от дублей с параметрами sort, order, limit, filter, page (noindex,follow для технических URL)&lt;/li&gt;&lt;li&gt;✅ Необязательный canonical на чистую категорию&lt;/li&gt;&lt;li&gt;✅ Фоновое изображение сайта через менеджер изображений OpenCart&lt;/li&gt;&lt;li&gt;✅ Промо-блоки и настройки оформления из админки&lt;/li&gt;&lt;li&gt;✅ Блог и отзывы в составе решения&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Установите тему и обновите модификаторы&lt;/li&gt;&lt;li&gt;2️⃣ Настройте цвета, блоки и разметку в админке&lt;/li&gt;&lt;li&gt;3️⃣ Проверьте витрину на мобильных устройствах и скорость&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Тема затрагивает почти всю витрину — проверяйте совместимость с другими модулями.&lt;/li&gt;&lt;li&gt;✅ Canonical включайте, только если SEO-модуль не выводит свой.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Адаптивная тема&lt;/li&gt;&lt;li&gt;✅ schema.org&lt;/li&gt;&lt;li&gt;✅ OpenCart 3.x&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;OpenCart Theme PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='OpenCart Theme PRO — самостоятельная коммерческая тема-витрина для OpenCart/ocStore 3.x: адаптивный каталог, современные карточки товаров, навигация…' WHERE `product_id`=92 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;VAT Price Input PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;VAT Price Input PRO&lt;/strong&gt; спрощує введення цін, коли в одному магазині продаються товари різних юридичних осіб: ФОП без ПДВ і ТОВ з ПДВ.&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Для товару ТОВ ви вводите підсумкову ціну з ПДВ, а модуль рахує ціну без податку й зберігає її в штатні поля.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ ФОП: ціни зберігаються як є, податковий клас примусово «Без податку»&lt;/li&gt;&lt;li&gt;✅ ТОВ: підсумкова ціна з ПДВ переводиться в нетто під час збереження — основна ціна, знижки, акції та надбавки опцій&lt;/li&gt;&lt;li&gt;✅ Ставка ПДВ залишається в штатних податкових класах і ставках OpenCart; вітрина застосовує їх звичайним способом&lt;/li&gt;&lt;li&gt;✅ Необов’язковий рядок ПДВ під ціною: «ПДВ включено: …» або «Ціна без ПДВ: …», колір тексту налаштовується&lt;/li&gt;&lt;li&gt;✅ Попередження в адмінці, якщо вимкнено штатне налаштування «Показувати ціни з податком» — модуль не змінює його сам&lt;/li&gt;&lt;li&gt;✅ Необов’язковий міст із Product Currency Input PRO для поєднання «ФОП/ТОВ + валюта»&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Увімкніть модуль і налаштуйте податковий клас для товарів ТОВ&lt;/li&gt;&lt;li&gt;2️⃣ У картці товару оберіть режим і введіть ціну з ПДВ&lt;/li&gt;&lt;li&gt;3️⃣ Перевірте ціну на вітрині, у кошику й у замовленні&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Для «ціни з податком» на вітрині ввімкніть штатне налаштування OpenCart.&lt;/li&gt;&lt;li&gt;✅ Податкову коректність перевіряйте разом із бухгалтером.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ ФОП / ТОВ&lt;/li&gt;&lt;li&gt;✅ Ціна з ПДВ → нетто&lt;/li&gt;&lt;li&gt;✅ Рядок ПДВ&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;VAT Price Input PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='VAT Price Input PRO спрощує введення цін, коли в одному магазині продаються товари різних юридичних осіб: ФОП без ПДВ і ТОВ з ПДВ. Для товару ТОВ ви вводите…' WHERE `product_id`=93 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;VAT Price Input PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;VAT Price Input PRO&lt;/strong&gt; simplifies price entry when one store sells products of different legal entities: sole proprietors (FOP) without VAT and companies (TOV) with VAT.&lt;/p&gt;&lt;h3&gt;💡 Why you need it&lt;/h3&gt;&lt;p&gt;For a TOV product you enter the final price including VAT and the module calculates the net price and stores it in the standard fields.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ FOP: prices are stored unchanged and the tax class is forced to “No tax”&lt;/li&gt;&lt;li&gt;✅ TOV: the VAT-inclusive price is converted to net on save — main price, discounts, specials and option adjustments&lt;/li&gt;&lt;li&gt;✅ The VAT rate stays in the standard OpenCart tax classes and rates; the storefront applies them as usual&lt;/li&gt;&lt;li&gt;✅ An optional VAT line under the price: “VAT included: …” or “Price excluding VAT: …” with a configurable text color&lt;/li&gt;&lt;li&gt;✅ An admin warning when the standard “Display prices with tax” setting is off — the module never changes it silently&lt;/li&gt;&lt;li&gt;✅ An optional bridge with Product Currency Input PRO for combined “FOP/TOV + currency” pricing&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Enable the module and set the tax class for TOV products&lt;/li&gt;&lt;li&gt;2️⃣ On the product page choose the mode and enter the price including VAT&lt;/li&gt;&lt;li&gt;3️⃣ Check the price on the storefront, in the cart and in the order&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ For VAT-inclusive storefront prices, enable the standard OpenCart setting.&lt;/li&gt;&lt;li&gt;✅ Verify tax correctness with your accountant.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ FOP / TOV&lt;/li&gt;&lt;li&gt;✅ VAT price → net&lt;/li&gt;&lt;li&gt;✅ VAT line&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Three-language interface&lt;/h3&gt;&lt;p&gt;The module admin is available in Russian, Ukrainian and English — convenient for stores and teams working in different language environments.&lt;/p&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;VAT Price Input PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='VAT Price Input PRO simplifies price entry when one store sells products of different legal entities: sole proprietors (FOP) without VAT and companies (TOV)…' WHERE `product_id`=93 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;VAT Price Input PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;VAT Price Input PRO&lt;/strong&gt; упрощает ввод цен, когда в одном магазине продаются товары разных юридических лиц: ФОП без НДС и ТОВ с НДС.&lt;/p&gt;&lt;h3&gt;💡 Зачем нужен модуль&lt;/h3&gt;&lt;p&gt;Для товара ТОВ вы вводите итоговую цену с НДС, а модуль считает цену без налога и сохраняет её в штатные поля.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ ФОП: цены сохраняются как есть, налоговый класс принудительно «Без налога»&lt;/li&gt;&lt;li&gt;✅ ТОВ: итоговая цена с НДС переводится в нетто при сохранении — основная цена, скидки, акции и надбавки опций&lt;/li&gt;&lt;li&gt;✅ Ставка НДС остаётся в штатных налоговых классах и ставках OpenCart; витрина применяет их обычным образом&lt;/li&gt;&lt;li&gt;✅ Необязательная строка НДС под ценой: «НДС включён: …» или «Цена без НДС: …», цвет текста настраивается&lt;/li&gt;&lt;li&gt;✅ Предупреждение в админке, если выключена штатная настройка «Показывать цены с налогом» — модуль не меняет её сам&lt;/li&gt;&lt;li&gt;✅ Необязательный мост с Product Currency Input PRO для сочетания «ФОП/ТОВ + валюта»&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Включите модуль и настройте налоговый класс для товаров ТОВ&lt;/li&gt;&lt;li&gt;2️⃣ В карточке товара выберите режим и введите цену с НДС&lt;/li&gt;&lt;li&gt;3️⃣ Проверьте цену на витрине, в корзине и в заказе&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Для «цены с налогом» на витрине включите штатную настройку OpenCart.&lt;/li&gt;&lt;li&gt;✅ Налоговую корректность проверяйте вместе с бухгалтером.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ ФОП / ТОВ&lt;/li&gt;&lt;li&gt;✅ Цена с НДС → нетто&lt;/li&gt;&lt;li&gt;✅ Строка НДС&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;VAT Price Input PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='VAT Price Input PRO упрощает ввод цен, когда в одном магазине продаются товары разных юридических лиц: ФОП без НДС и ТОВ с НДС. Для товара ТОВ вы вводите…' WHERE `product_id`=93 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Supplier Sync Parser PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Supplier Sync Parser PRO&lt;/strong&gt; забирає ціни, залишки, дані й нові товари з сайтів постачальників, коли в постачальника немає XML, CSV чи API.&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Робота побудована навколо простого майстра: скануйте сторінку товару, перевірте знайдені значення, збережіть правила й застосуйте перевірені зміни.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ HTML-парсинг і XPath-правила за майстром «просканувати одну сторінку товару»&lt;/li&gt;&lt;li&gt;✅ Моніторинг цін і залишків на сайтах постачальників&lt;/li&gt;&lt;li&gt;✅ Безпечний попередній перегляд перед застосуванням змін до товарів OpenCart&lt;/li&gt;&lt;li&gt;✅ Зіставлення наявних товарів за SKU, EAN, UPC, MPN, URL постачальника й назвою&lt;/li&gt;&lt;li&gt;✅ Захоплення нових товарів із ручним вибором категорії до створення&lt;/li&gt;&lt;li&gt;✅ Валюти OpenCart і нормалізація ціни постачальника; вибір мови для багатомовних магазинів&lt;/li&gt;&lt;li&gt;✅ Черга для пакетної обробки великих каталогів, AJAX, фільтри та пагінація&lt;/li&gt;&lt;li&gt;✅ Журнали, історія й зведення запусків; у вимкненому стані черга, cron і парсинг не працюють&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Створіть профіль постачальника: URL, валюта, мова, категорії&lt;/li&gt;&lt;li&gt;2️⃣ Просканіть один товар, перевірте знайдені поля й збережіть правила&lt;/li&gt;&lt;li&gt;3️⃣ Складіть чергу, обробіть невеликий пакет і перевірте попередній перегляд&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Парсіть лише те, що ви маєте право використовувати, і враховуйте навантаження на сайт постачальника.&lt;/li&gt;&lt;li&gt;✅ Перший запуск — малою партією.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ XPath&lt;/li&gt;&lt;li&gt;✅ Черга + cron&lt;/li&gt;&lt;li&gt;✅ Попередній перегляд&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Supplier Sync Parser PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Supplier Sync Parser PRO забирає ціни, залишки, дані й нові товари з сайтів постачальників, коли в постачальника немає XML, CSV чи API. Робота побудована…' WHERE `product_id`=94 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Supplier Sync Parser PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Supplier Sync Parser PRO&lt;/strong&gt; pulls prices, stock, product data and new products from supplier websites when the supplier offers no XML, CSV or API.&lt;/p&gt;&lt;h3&gt;💡 Why you need it&lt;/h3&gt;&lt;p&gt;The workflow is built around a simple wizard: scan one product page, check the detected values, save the rules and apply the reviewed changes.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ HTML parsing and XPath rules behind a “scan one product page” wizard&lt;/li&gt;&lt;li&gt;✅ Price and stock monitoring on supplier websites&lt;/li&gt;&lt;li&gt;✅ A safe preview before changes are applied to OpenCart products&lt;/li&gt;&lt;li&gt;✅ Matching of existing products by SKU, EAN, UPC, MPN, supplier URL and title&lt;/li&gt;&lt;li&gt;✅ New-product capture with manual category selection before creation&lt;/li&gt;&lt;li&gt;✅ OpenCart currencies and supplier price normalization; language targeting for multilingual stores&lt;/li&gt;&lt;li&gt;✅ A queue for batch processing of large catalogs, AJAX, filters and pagination&lt;/li&gt;&lt;li&gt;✅ Logs, history and run summaries; while the module is off the queue, cron and parsing do not run&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Create a supplier profile: URL, currency, language, categories&lt;/li&gt;&lt;li&gt;2️⃣ Scan one product, check the detected fields and save the rules&lt;/li&gt;&lt;li&gt;3️⃣ Build a queue, process a small batch and review the preview&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Parse only what you are entitled to use and mind the load on the supplier’s site.&lt;/li&gt;&lt;li&gt;✅ Start with a small batch.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ XPath&lt;/li&gt;&lt;li&gt;✅ Queue + cron&lt;/li&gt;&lt;li&gt;✅ Preview&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Three-language interface&lt;/h3&gt;&lt;p&gt;The module admin is available in Russian, Ukrainian and English — convenient for stores and teams working in different language environments.&lt;/p&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Supplier Sync Parser PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Supplier Sync Parser PRO pulls prices, stock, product data and new products from supplier websites when the supplier offers no XML, CSV or API. The workflow…' WHERE `product_id`=94 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Supplier Sync Parser PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Supplier Sync Parser PRO&lt;/strong&gt; забирает цены, остатки, данные и новые товары с сайтов поставщиков, когда у поставщика нет XML, CSV или API.&lt;/p&gt;&lt;h3&gt;💡 Зачем нужен модуль&lt;/h3&gt;&lt;p&gt;Работа построена вокруг простого мастера: сканируйте страницу товара, проверьте найденные значения, сохраните правила и примените проверенные изменения.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ HTML-парсинг и XPath-правила за мастером «просканировать одну страницу товара»&lt;/li&gt;&lt;li&gt;✅ Мониторинг цен и остатков на сайтах поставщиков&lt;/li&gt;&lt;li&gt;✅ Безопасный предпросмотр перед применением изменений к товарам OpenCart&lt;/li&gt;&lt;li&gt;✅ Сопоставление существующих товаров по SKU, EAN, UPC, MPN, URL поставщика и названию&lt;/li&gt;&lt;li&gt;✅ Захват новых товаров с ручным выбором категории до создания&lt;/li&gt;&lt;li&gt;✅ Валюты OpenCart и нормализация цены поставщика; выбор языка для мультиязычных магазинов&lt;/li&gt;&lt;li&gt;✅ Очередь для пакетной обработки больших каталогов, AJAX, фильтры и пагинация&lt;/li&gt;&lt;li&gt;✅ Журналы, история и сводки запусков; в выключенном состоянии очередь, cron и парсинг не работают&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Создайте профиль поставщика: URL, валюта, язык, категории&lt;/li&gt;&lt;li&gt;2️⃣ Просканируйте один товар, проверьте найденные поля и сохраните правила&lt;/li&gt;&lt;li&gt;3️⃣ Соберите очередь, обработайте небольшой пакет и проверьте предпросмотр&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Парсите только то, что вы вправе использовать, и учитывайте нагрузку на сайт поставщика.&lt;/li&gt;&lt;li&gt;✅ Первый запуск — маленьким пакетом.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ XPath&lt;/li&gt;&lt;li&gt;✅ Очередь + cron&lt;/li&gt;&lt;li&gt;✅ Предпросмотр&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Supplier Sync Parser PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Supplier Sync Parser PRO забирает цены, остатки, данные и новые товары с сайтов поставщиков, когда у поставщика нет XML, CSV или API. Работа построена вокруг…' WHERE `product_id`=94 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Source Copy Protection PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Source Copy Protection PRO&lt;/strong&gt; додає посилання на джерело до копійованого тексту й, за потреби, блокує контекстне меню, виділення, перетягування та типові гарячі клавіші копіювання.&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Групи сторінок і окремі маршрути налаштовуються незалежно.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Режими: «Немає», «Додавати джерело», «Максимальне блокування» та «Джерело + технічне блокування»&lt;/li&gt;&lt;li&gt;✅ Під час копіювання в буфер додається налаштований текст із посиланням на джерело&lt;/li&gt;&lt;li&gt;✅ Блокування правої кнопки (поза винятками селекторів або скрізь), виділення, перетягування, подій copy і cut та типових клавіш копіювання й інструментів розробника&lt;/li&gt;&lt;li&gt;✅ Групи сторінок і власні маршрути з окремими налаштуваннями&lt;/li&gt;&lt;li&gt;✅ У вимкненому стані немає подій вітрини, JavaScript, CSS і додаткових запитів&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Оберіть режим і тексти джерела&lt;/li&gt;&lt;li&gt;2️⃣ Вкажіть групи сторінок і винятки&lt;/li&gt;&lt;li&gt;3️⃣ Перевірте копіювання на вітрині й увімкніть модуль&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Захист від копіювання не зупинить технічно підготовленої людини — модуль знижує просте копіювання й повертає посилання на джерело.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Посилання на джерело&lt;/li&gt;&lt;li&gt;✅ Блокування копіювання&lt;/li&gt;&lt;li&gt;✅ Маршрути й групи&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Source Copy Protection PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Source Copy Protection PRO додає посилання на джерело до копійованого тексту й, за потреби, блокує контекстне меню, виділення, перетягування та типові гарячі…' WHERE `product_id`=95 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Source Copy Protection PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Source Copy Protection PRO&lt;/strong&gt; appends a source link to copied text and, when needed, blocks the context menu, text selection, dragging and the usual copy hotkeys.&lt;/p&gt;&lt;h3&gt;💡 Why you need it&lt;/h3&gt;&lt;p&gt;Page groups and individual routes are configured independently.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Modes: None, Append source, Maximum blocking and Append source + technical blocking&lt;/li&gt;&lt;li&gt;✅ The configured text with a source link is appended to the clipboard on copy&lt;/li&gt;&lt;li&gt;✅ Blocking of right-click (outside excluded selectors or everywhere), selection, dragging, copy and cut events and common copy and developer hotkeys&lt;/li&gt;&lt;li&gt;✅ Page groups and custom routes with separate settings&lt;/li&gt;&lt;li&gt;✅ While off there are no storefront events, JavaScript, CSS or extra requests&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Choose the mode and the source texts&lt;/li&gt;&lt;li&gt;2️⃣ Specify page groups and exclusions&lt;/li&gt;&lt;li&gt;3️⃣ Test copying on the storefront and enable the module&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Copy protection cannot stop a technically skilled person — the module reduces casual copying and brings back a link to the source.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Source link&lt;/li&gt;&lt;li&gt;✅ Copy blocking&lt;/li&gt;&lt;li&gt;✅ Routes and groups&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Source Copy Protection PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Source Copy Protection PRO appends a source link to copied text and, when needed, blocks the context menu, text selection, dragging and the usual copy…' WHERE `product_id`=95 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Source Copy Protection PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Source Copy Protection PRO&lt;/strong&gt; добавляет ссылку на источник к копируемому тексту и, при необходимости, блокирует контекстное меню, выделение, перетаскивание и типовые горячие клавиши копирования.&lt;/p&gt;&lt;h3&gt;💡 Зачем нужен модуль&lt;/h3&gt;&lt;p&gt;Группы страниц и отдельные маршруты настраиваются независимо.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Режимы: «Нет», «Добавлять источник», «Максимальная блокировка» и «Источник + техническая блокировка»&lt;/li&gt;&lt;li&gt;✅ При копировании в буфер добавляется настроенный текст со ссылкой на источник&lt;/li&gt;&lt;li&gt;✅ Блокировка правой кнопки (вне исключённых селекторов или везде), выделения, перетаскивания, событий copy и cut и типовых клавиш копирования и инструментов разработчика&lt;/li&gt;&lt;li&gt;✅ Группы страниц и собственные маршруты с отдельными настройками&lt;/li&gt;&lt;li&gt;✅ В выключенном состоянии нет событий витрины, JavaScript, CSS и дополнительных запросов&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Выберите режим и тексты источника&lt;/li&gt;&lt;li&gt;2️⃣ Укажите группы страниц и исключения&lt;/li&gt;&lt;li&gt;3️⃣ Проверьте копирование на витрине и включите модуль&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Защита от копирования не остановит технически подготовленного человека — модуль снижает простое копирование и возвращает ссылку на источник.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Ссылка на источник&lt;/li&gt;&lt;li&gt;✅ Блокировка копирования&lt;/li&gt;&lt;li&gt;✅ Маршруты и группы&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Source Copy Protection PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Source Copy Protection PRO добавляет ссылку на источник к копируемому тексту и, при необходимости, блокирует контекстное меню, выделение, перетаскивание и…' WHERE `product_id`=95 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Social Login PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Social Login PRO&lt;/strong&gt; додає безпечний вхід, реєстрацію та прив’язку акаунтів покупців через Google, Apple, Facebook, Microsoft, PayPal, LinkedIn, Яндекс, Telegram і VK.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Дев’ять OAuth/OIDC-провайдерів&lt;/li&gt;&lt;li&gt;✅ Стандартні сторінки OpenCart account/login, account/register, checkout/login та UniShop2 checkout і вікно входу&lt;/li&gt;&lt;li&gt;✅ Окреме ввімкнення для входу, реєстрації, стандартного checkout і UniShop2&lt;/li&gt;&lt;li&gt;✅ Прив’язка й відв’язка соцакаунтів у кабінеті покупця&lt;/li&gt;&lt;li&gt;✅ Зв’язування з наявним клієнтом за email лише там, де провайдер справді підтверджує email&lt;/li&gt;&lt;li&gt;✅ Запит відсутніх обов’язкових даних (ім’я, прізвище, телефон) перед створенням клієнта&lt;/li&gt;&lt;li&gt;✅ Підписи кнопок усіма мовами; стилі Brand, Neutral, Outline і Auto; форми Rounded, Pill, Square; живий попередній перегляд&lt;/li&gt;&lt;li&gt;✅ Агрегована статистика без зберігання персональних OAuth-даних; діагностика й перевірка налаштувань&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Зареєструйте застосунки в потрібних провайдерів і введіть ключі&lt;/li&gt;&lt;li&gt;2️⃣ Оберіть місця показу й оформлення кнопок&lt;/li&gt;&lt;li&gt;3️⃣ Перевірте вхід і реєстрацію на тестовому акаунті&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Для кожного провайдера потрібно створити застосунок і отримати client ID та secret у його консолі розробника.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Google · Apple · Facebook · Telegram&lt;/li&gt;&lt;li&gt;✅ 9 провайдерів&lt;/li&gt;&lt;li&gt;✅ UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Інтерфейс трьома мовами&lt;/h3&gt;&lt;p&gt;Адмінка модуля доступна російською, українською та англійською мовами — зручно для магазинів і команд, які працюють у різних мовних середовищах.&lt;/p&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Social Login PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Social Login PRO додає безпечний вхід, реєстрацію та прив’язку акаунтів покупців через Google, Apple, Facebook, Microsoft, PayPal, LinkedIn, Яндекс, Telegram…' WHERE `product_id`=96 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Social Login PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Social Login PRO&lt;/strong&gt; adds secure sign-in, registration and account linking for customers through Google, Apple, Facebook, Microsoft, PayPal, LinkedIn, Yandex, Telegram and VK.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Nine OAuth/OIDC providers&lt;/li&gt;&lt;li&gt;✅ Stock OpenCart account/login, account/register and checkout/login pages plus UniShop2 checkout and the login window&lt;/li&gt;&lt;li&gt;✅ Independent switches for sign-in, registration, stock checkout and UniShop2&lt;/li&gt;&lt;li&gt;✅ Customers can link and unlink social accounts in their account area&lt;/li&gt;&lt;li&gt;✅ Existing customers are linked by e-mail only where the provider really verifies the e-mail&lt;/li&gt;&lt;li&gt;✅ Missing required data (first name, last name, phone) is requested before a customer is created&lt;/li&gt;&lt;li&gt;✅ Button labels in every language; Brand, Neutral, Outline and Auto styles; Rounded, Pill and Square shapes; live preview&lt;/li&gt;&lt;li&gt;✅ Aggregated statistics without storing personal OAuth data; diagnostics and a settings check&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Register apps with the providers you need and enter the keys&lt;/li&gt;&lt;li&gt;2️⃣ Choose where to show the buttons and how they look&lt;/li&gt;&lt;li&gt;3️⃣ Test sign-in and registration with a test account&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ For each provider you must create an app and obtain a client ID and secret in its developer console.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Google · Apple · Facebook · Telegram&lt;/li&gt;&lt;li&gt;✅ 9 providers&lt;/li&gt;&lt;li&gt;✅ UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Three-language interface&lt;/h3&gt;&lt;p&gt;The module admin is available in Russian, Ukrainian and English — convenient for stores and teams working in different language environments.&lt;/p&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Social Login PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Social Login PRO adds secure sign-in, registration and account linking for customers through Google, Apple, Facebook, Microsoft, PayPal, LinkedIn, Yandex…' WHERE `product_id`=96 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Social Login PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Social Login PRO&lt;/strong&gt; добавляет безопасный вход, регистрацию и привязку аккаунтов покупателей через Google, Apple, Facebook, Microsoft, PayPal, LinkedIn, Яндекс, Telegram и VK.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Девять OAuth/OIDC-провайдеров&lt;/li&gt;&lt;li&gt;✅ Стандартные страницы OpenCart account/login, account/register, checkout/login и UniShop2 checkout и окно входа&lt;/li&gt;&lt;li&gt;✅ Отдельное включение для входа, регистрации, стандартного checkout и UniShop2&lt;/li&gt;&lt;li&gt;✅ Привязка и отвязка соцаккаунтов в кабинете покупателя&lt;/li&gt;&lt;li&gt;✅ Связывание с существующим клиентом по email только там, где провайдер действительно подтверждает email&lt;/li&gt;&lt;li&gt;✅ Запрос недостающих обязательных данных (имя, фамилия, телефон) перед созданием клиента&lt;/li&gt;&lt;li&gt;✅ Подписи кнопок на всех языках; стили Brand, Neutral, Outline и Auto; формы Rounded, Pill, Square; живой предпросмотр&lt;/li&gt;&lt;li&gt;✅ Агрегированная статистика без хранения персональных OAuth-данных; диагностика и проверка настроек&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Зарегистрируйте приложения у нужных провайдеров и введите ключи&lt;/li&gt;&lt;li&gt;2️⃣ Выберите места показа и оформление кнопок&lt;/li&gt;&lt;li&gt;3️⃣ Проверьте вход и регистрацию на тестовом аккаунте&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Для каждого провайдера нужно создать приложение и получить client ID и secret в его консоли разработчика.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Google · Apple · Facebook · Telegram&lt;/li&gt;&lt;li&gt;✅ 9 провайдеров&lt;/li&gt;&lt;li&gt;✅ UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Интерфейс на трёх языках&lt;/h3&gt;&lt;p&gt;Админка модуля доступна на русском, украинском и английском языках — удобно для магазинов и команд, работающих в разных языковых средах.&lt;/p&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Social Login PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Social Login PRO добавляет безопасный вход, регистрацию и привязку аккаунтов покупателей через Google, Apple, Facebook, Microsoft, PayPal, LinkedIn, Яндекс…' WHERE `product_id`=96 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;SMSfly Order PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;SMSfly Order PRO&lt;/strong&gt; надсилає SMS і Viber сповіщення за замовленнями OpenCart/ocStore, дозволяє писати клієнтові просто із замовлення та підтримує інтеграцію з Новою Поштою й швидкими замовленнями UniShop2.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ SMS/Viber сповіщення клієнту й менеджеру за замовленнями&lt;/li&gt;&lt;li&gt;✅ Ручне надсилання повідомлення зі сторінки замовлення&lt;/li&gt;&lt;li&gt;✅ Інтеграція з Nova Poshta: сповіщення за відправленнями&lt;/li&gt;&lt;li&gt;✅ Окремі сповіщення для UniShop2 Quick Order&lt;/li&gt;&lt;li&gt;✅ Шаблони повідомлень для клієнта, менеджера та швидкого замовлення&lt;/li&gt;&lt;li&gt;✅ Підказки щодо налаштування API й шаблонів просто в адмінці&lt;/li&gt;&lt;li&gt;✅ Сумісність: ocStore 3.0.4.1, OpenCart 3.x, PHP 7.4–8.5, MySQL/MariaDB&lt;/li&gt;&lt;li&gt;✅ Встановлюється вимкненим — вмикається вручну після налаштування API&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Введіть дані API SMSfly та налаштуйте шаблони&lt;/li&gt;&lt;li&gt;2️⃣ Увімкніть модуль і збережіть налаштування&lt;/li&gt;&lt;li&gt;3️⃣ Перевірте надсилання на тестовому замовленні&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Потрібен акаунт SMS-Fly; вартість повідомлень визначається тарифами сервісу.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ SMS-Fly&lt;/li&gt;&lt;li&gt;✅ SMS · Viber&lt;/li&gt;&lt;li&gt;✅ Nova Poshta&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;SMSfly Order PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='SMSfly Order PRO надсилає SMS і Viber сповіщення за замовленнями OpenCart/ocStore, дозволяє писати клієнтові просто із замовлення та підтримує інтеграцію з…' WHERE `product_id`=97 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;SMSfly Order PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;SMSfly Order PRO&lt;/strong&gt; sends SMS and Viber notifications for OpenCart/ocStore orders, lets you message a customer straight from the order page and integrates with Nova Poshta and UniShop2 quick orders.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ SMS/Viber notifications to customers and managers about orders&lt;/li&gt;&lt;li&gt;✅ Manual message sending from the order page&lt;/li&gt;&lt;li&gt;✅ Nova Poshta integration: shipment notifications&lt;/li&gt;&lt;li&gt;✅ Separate notifications for UniShop2 Quick Order&lt;/li&gt;&lt;li&gt;✅ Message templates for the customer, the manager and quick orders&lt;/li&gt;&lt;li&gt;✅ Hints for API and template setup right in the admin&lt;/li&gt;&lt;li&gt;✅ Compatibility: ocStore 3.0.4.1, OpenCart 3.x, PHP 7.4–8.5, MySQL/MariaDB&lt;/li&gt;&lt;li&gt;✅ Installed switched off — you enable it manually after configuring the API&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Enter the SMSfly API details and set up the templates&lt;/li&gt;&lt;li&gt;2️⃣ Enable the module and save the settings&lt;/li&gt;&lt;li&gt;3️⃣ Verify sending with a test order&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ An SMS-Fly account is required; message cost follows the service’s tariffs.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ SMS-Fly&lt;/li&gt;&lt;li&gt;✅ SMS · Viber&lt;/li&gt;&lt;li&gt;✅ Nova Poshta&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Three-language interface&lt;/h3&gt;&lt;p&gt;The module admin is available in Russian, Ukrainian and English — convenient for stores and teams working in different language environments.&lt;/p&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;SMSfly Order PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='SMSfly Order PRO sends SMS and Viber notifications for OpenCart/ocStore orders, lets you message a customer straight from the order page and integrates with…' WHERE `product_id`=97 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;SMSfly Order PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;SMSfly Order PRO&lt;/strong&gt; отправляет SMS и Viber уведомления по заказам OpenCart/ocStore, позволяет писать клиенту прямо из заказа и поддерживает интеграцию с Новой Почтой и быстрыми заказами UniShop2.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ SMS/Viber уведомления клиенту и менеджеру по заказам&lt;/li&gt;&lt;li&gt;✅ Ручная отправка сообщения со страницы заказа&lt;/li&gt;&lt;li&gt;✅ Интеграция с Nova Poshta: уведомления по отправлениям&lt;/li&gt;&lt;li&gt;✅ Отдельные уведомления для UniShop2 Quick Order&lt;/li&gt;&lt;li&gt;✅ Шаблоны сообщений для клиента, менеджера и быстрого заказа&lt;/li&gt;&lt;li&gt;✅ Подсказки по настройке API и шаблонов прямо в админке&lt;/li&gt;&lt;li&gt;✅ Совместимость: ocStore 3.0.4.1, OpenCart 3.x, PHP 7.4–8.5, MySQL/MariaDB&lt;/li&gt;&lt;li&gt;✅ Устанавливается выключенным — включается вручную после настройки API&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Введите данные API SMSfly и настройте шаблоны&lt;/li&gt;&lt;li&gt;2️⃣ Включите модуль и сохраните настройки&lt;/li&gt;&lt;li&gt;3️⃣ Проверьте отправку на тестовом заказе&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Нужен аккаунт SMS-Fly; стоимость сообщений определяется тарифами сервиса.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ SMS-Fly&lt;/li&gt;&lt;li&gt;✅ SMS · Viber&lt;/li&gt;&lt;li&gt;✅ Nova Poshta&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;SMSfly Order PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='SMSfly Order PRO отправляет SMS и Viber уведомления по заказам OpenCart/ocStore, позволяет писать клиенту прямо из заказа и поддерживает интеграцию с Новой…' WHERE `product_id`=97 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;SEO URL Generator FREE&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;SEO URL Generator FREE&lt;/strong&gt; — безкоштовний базовий інструмент для зрозумілих SEO URL та окремих редиректів в OpenCart/ocStore.&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Для магазинів, яким потрібен легкий генератор ЧПУ без повного набору автоматизації платного SEO URL PRO.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Генерація SEO URL для товарів, категорій, виробників та інших сутностей&lt;/li&gt;&lt;li&gt;✅ Власні редиректи для товарів, категорій і виробників — коли потрібно призначити інше посилання&lt;/li&gt;&lt;li&gt;✅ Опція оновлення старого SEO URL, коли змінюється назва сутності&lt;/li&gt;&lt;li&gt;✅ Сумісність: CodeCart 3.0.5.2, OpenCart 3.x, ocStore 3.0.4.1, PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;✅ Суворий режим OFF: події UniShop2 News створюються лише після ручного вмикання&lt;/li&gt;&lt;li&gt;✅ Безкоштовно; для масової генерації за сотнями товарів і діагностики є SEO URL PRO&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Встановіть і ввімкніть модуль&lt;/li&gt;&lt;li&gt;2️⃣ Відкрийте товар чи категорію та згенеруйте SEO URL&lt;/li&gt;&lt;li&gt;3️⃣ За зміни адреси додайте редирект&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Безкоштовна версія не замінює масову генерацію й розширену діагностику SEO URL PRO.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Б