UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;SEO Meta Character Counter PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;SEO Meta Character Counter PRO&lt;/strong&gt; показує живі лічильники символів поруч із SEO-полями в адмінці OpenCart.&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Він нічого не генерує й не змінює — лише допомагає вписатися в рекомендовану довжину під час написання.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Лічильники для назви, H1, Meta Title, Meta Description та інших підтримуваних полів&lt;/li&gt;&lt;li&gt;✅ Працюють у формах товарів, категорій, інформації, виробників і сумісних сторінок блогу/новин&lt;/li&gt;&lt;li&gt;✅ Підказки щодо довжини під час введення&lt;/li&gt;&lt;li&gt;✅ Не змінюють значення, що зберігається&lt;/li&gt;&lt;li&gt;✅ Не потрібні окремі таблиці, cron або фонові задачі&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Встановіть і увімкніть модуль&lt;/li&gt;&lt;li&gt;2️⃣ Відкрийте форму товару чи категорії&lt;/li&gt;&lt;li&gt;3️⃣ Стежте за лічильником під час введення тексту&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Це лише індикатор: рекомендована довжина залежить від пошукової системи й мови.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Адмінка&lt;/li&gt;&lt;li&gt;✅ Meta Title · Description&lt;/li&gt;&lt;li&gt;✅ Без cron&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;SEO Meta Character Counter PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='SEO Meta Character Counter PRO показує живі лічильники символів поруч із SEO-полями в адмінці OpenCart. Він нічого не генерує й не змінює — лише допомагає…' WHERE `product_id`=99 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;SEO Meta Character Counter PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;SEO Meta Character Counter PRO&lt;/strong&gt; shows live character counters next to SEO fields in the OpenCart admin.&lt;/p&gt;&lt;h3&gt;💡 Why you need it&lt;/h3&gt;&lt;p&gt;It generates and changes nothing — it only helps you stay within the recommended length while you type.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Counters for name, H1, Meta Title, Meta Description and other supported fields&lt;/li&gt;&lt;li&gt;✅ Work in product, category, information and manufacturer forms and compatible blog/news pages&lt;/li&gt;&lt;li&gt;✅ Length hints while typing&lt;/li&gt;&lt;li&gt;✅ Never change the saved value&lt;/li&gt;&lt;li&gt;✅ No extra tables, cron or background tasks&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Install and enable the module&lt;/li&gt;&lt;li&gt;2️⃣ Open a product or category form&lt;/li&gt;&lt;li&gt;3️⃣ Watch the counter as you type&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ It is an indicator only: the recommended length depends on the search engine and language.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Admin&lt;/li&gt;&lt;li&gt;✅ Meta Title · Description&lt;/li&gt;&lt;li&gt;✅ No cron&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;SEO Meta Character Counter PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='SEO Meta Character Counter PRO shows live character counters next to SEO fields in the OpenCart admin. It generates and changes nothing — it only helps you…' WHERE `product_id`=99 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;SEO Meta Character Counter PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;SEO Meta Character Counter PRO&lt;/strong&gt; показывает живые счётчики символов рядом с SEO-полями в админке OpenCart.&lt;/p&gt;&lt;h3&gt;💡 Зачем нужен модуль&lt;/h3&gt;&lt;p&gt;Он ничего не генерирует и не меняет — только помогает вписаться в рекомендуемую длину, пока вы пишете.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Счётчики для названия, H1, Meta Title, Meta Description и других поддерживаемых полей&lt;/li&gt;&lt;li&gt;✅ Работают в формах товаров, категорий, информации, производителей и совместимых страниц блога/новостей&lt;/li&gt;&lt;li&gt;✅ Подсказки по длине при вводе&lt;/li&gt;&lt;li&gt;✅ Не меняют сохраняемое значение&lt;/li&gt;&lt;li&gt;✅ Не нужны отдельные таблицы, cron или фоновые задачи&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Установите и включите модуль&lt;/li&gt;&lt;li&gt;2️⃣ Откройте форму товара или категории&lt;/li&gt;&lt;li&gt;3️⃣ Следите за счётчиком при вводе текста&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Это только индикатор: рекомендуемая длина зависит от поисковой системы и языка.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Админка&lt;/li&gt;&lt;li&gt;✅ Meta Title · Description&lt;/li&gt;&lt;li&gt;✅ Без cron&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;SEO Meta Character Counter PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='SEO Meta Character Counter PRO показывает живые счётчики символов рядом с SEO-полями в админке OpenCart. Он ничего не генерирует и не меняет — только…' WHERE `product_id`=99 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;reCAPTCHA Security PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;reCAPTCHA Security PRO&lt;/strong&gt; перевіряє відвідувача через Google reCAPTCHA або hCaptcha, приховане антиспам-поле, час заповнення форми й точні маршрутні політики — на сервері, до виконання захищеної дії.&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Працює зі стандартними формами OpenCart і може захищати нестандартні POST/AJAX-обробники.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Google reCAPTCHA або hCaptcha, приховане антиспам-поле й контроль мінімального часу заповнення&lt;/li&gt;&lt;li&gt;✅ Серверна перевірка hostname та action, пороги ризику; окремі пороги для реєстрації, відгуків, входу й checkout&lt;/li&gt;&lt;li&gt;✅ Відкладене завантаження: Google JavaScript не завантажується заздалегідь у режимі «під час надсилання»&lt;/li&gt;&lt;li&gt;✅ Захист контактів, входу, відновлення пароля й обраних форм; точні маршрути для форм UniShop2 і сторонніх модулів&lt;/li&gt;&lt;li&gt;✅ Тестовий режим для нестандартних форм — без блокування покупців&lt;/li&gt;&lt;li&gt;✅ Журнал із фільтрами, сортуванням, пагінацією та зрозумілими причинами; секретні ключі не повертаються в браузер&lt;/li&gt;&lt;li&gt;✅ У вимкненому стані немає подій вітрини й навантаження&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Створіть ключі в консолі провайдера для обраного режиму й домену&lt;/li&gt;&lt;li&gt;2️⃣ Задайте поріг (для v3 — 0,50), маршрутні політики та відкладене завантаження&lt;/li&gt;&lt;li&gt;3️⃣ Оберіть модуль CAPTCHA в налаштуваннях магазину й перевірте форми; нестандартні вмикайте спершу в тестовому режимі&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Стандартна CAPTCHA OpenCart захищає лише контролери, що її викликають, — цей модуль додає серверну перевірку й захист нестандартних форм.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ reCAPTCHA · hCaptcha&lt;/li&gt;&lt;li&gt;✅ Серверна перевірка&lt;/li&gt;&lt;li&gt;✅ Тестовий режим&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;reCAPTCHA Security PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='reCAPTCHA Security PRO перевіряє відвідувача через Google reCAPTCHA або hCaptcha, приховане антиспам-поле, час заповнення форми й точні маршрутні політики …' WHERE `product_id`=100 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;reCAPTCHA Security PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;reCAPTCHA Security PRO&lt;/strong&gt; verifies visitors through Google reCAPTCHA or hCaptcha, a hidden anti-spam field, form fill time and exact route policies — on the server, before the protected action runs.&lt;/p&gt;&lt;h3&gt;💡 Why you need it&lt;/h3&gt;&lt;p&gt;It works with standard OpenCart forms and can protect custom POST/AJAX handlers.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Google reCAPTCHA or hCaptcha, a hidden anti-spam field and a minimum fill-time check&lt;/li&gt;&lt;li&gt;✅ Server-side hostname and action validation and risk thresholds; separate thresholds for registration, reviews, login and checkout&lt;/li&gt;&lt;li&gt;✅ Deferred loading: Google JavaScript is not preloaded in “on submit” mode&lt;/li&gt;&lt;li&gt;✅ Protection for contact forms, login, password recovery and selected forms; exact routes for UniShop2 and third-party module forms&lt;/li&gt;&lt;li&gt;✅ A test mode for custom forms — without blocking customers&lt;/li&gt;&lt;li&gt;✅ A log with filters, sorting, pagination and clear reasons; secret keys never go back to the browser&lt;/li&gt;&lt;li&gt;✅ No storefront events or load while the module is off&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Create keys in the provider console for the chosen mode and domain&lt;/li&gt;&lt;li&gt;2️⃣ Set the threshold (0.50 for v3), route policies and deferred loading&lt;/li&gt;&lt;li&gt;3️⃣ Select the module as the store CAPTCHA and test the forms; enable custom forms in test mode first&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ The stock OpenCart CAPTCHA only protects controllers that call it — this module adds server-side verification and protection for custom forms.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ reCAPTCHA · hCaptcha&lt;/li&gt;&lt;li&gt;✅ Server-side check&lt;/li&gt;&lt;li&gt;✅ Test mode&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;reCAPTCHA Security PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='reCAPTCHA Security PRO verifies visitors through Google reCAPTCHA or hCaptcha, a hidden anti-spam field, form fill time and exact route policies — on the…' WHERE `product_id`=100 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;reCAPTCHA Security PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;reCAPTCHA Security PRO&lt;/strong&gt; проверяет посетителя через Google reCAPTCHA или hCaptcha, скрытое антиспам-поле, время заполнения формы и точные маршрутные политики — на сервере, до выполнения защищаемого действия.&lt;/p&gt;&lt;h3&gt;💡 Зачем нужен модуль&lt;/h3&gt;&lt;p&gt;Работает со стандартными формами OpenCart и может защищать нестандартные POST/AJAX-обработчики.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Google reCAPTCHA или hCaptcha, скрытое антиспам-поле и контроль минимального времени заполнения&lt;/li&gt;&lt;li&gt;✅ Серверная проверка hostname и action, пороги риска; отдельные пороги для регистрации, отзывов, входа и checkout&lt;/li&gt;&lt;li&gt;✅ Отложенная загрузка: Google JavaScript не загружается заранее при режиме «при отправке»&lt;/li&gt;&lt;li&gt;✅ Защита контактов, входа, восстановления пароля и выбранных форм; точные маршруты для форм UniShop2 и сторонних модулей&lt;/li&gt;&lt;li&gt;✅ Тестовый режим для нестандартных форм — без блокировки покупателей&lt;/li&gt;&lt;li&gt;✅ Журнал с фильтрами, сортировкой, пагинацией и понятными причинами; секретные ключи не возвращаются в браузер&lt;/li&gt;&lt;li&gt;✅ В выключенном состоянии нет событий витрины и нагрузки&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Создайте ключи в консоли провайдера для выбранного режима и домена&lt;/li&gt;&lt;li&gt;2️⃣ Задайте порог (для v3 — 0,50), маршрутные политики и отложенную загрузку&lt;/li&gt;&lt;li&gt;3️⃣ Выберите модуль CAPTCHA в настройках магазина и проверьте формы; нестандартные включайте сначала в тестовом режиме&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Стандартная CAPTCHA OpenCart защищает только вызывающие её контроллеры — этот модуль добавляет серверную проверку и защиту нестандартных форм.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ reCAPTCHA · hCaptcha&lt;/li&gt;&lt;li&gt;✅ Серверная проверка&lt;/li&gt;&lt;li&gt;✅ Тестовый режим&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;reCAPTCHA Security PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='reCAPTCHA Security PRO проверяет посетителя через Google reCAPTCHA или hCaptcha, скрытое антиспам-поле, время заполнения формы и точные маршрутные политики …' WHERE `product_id`=100 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Video Gallery PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Video Gallery PRO&lt;/strong&gt; показує відео YouTube, Vimeo, TikTok, Facebook, Rutube, VK і OK просто в галереї товару, покращуючи картку й SEO.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Відео в галереї товару: YouTube, Vimeo, TikTok, Facebook, Rutube, VK, OK&lt;/li&gt;&lt;li&gt;✅ Відео зберігаються в базі даних, а не в кеші; фінальне збереження — штатною кнопкою «Зберегти» товару&lt;/li&gt;&lt;li&gt;✅ Нормалізація YouTube iframe в описі товару: embed URL, title, allow і allowfullscreen&lt;/li&gt;&lt;li&gt;✅ Єдиний VideoObject JSON-LD для відео галереї та YouTube з опису — без дублів&lt;/li&gt;&lt;li&gt;✅ Зовнішні мініатюри кешуються локально й віддаються через image/cache&lt;/li&gt;&lt;li&gt;✅ М’яка інтеграція зі стандартною темою, UniShop2 і CodeCart PRO Theme&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Увімкніть модуль і перевірте провайдерів&lt;/li&gt;&lt;li&gt;2️⃣ У картці товару на вкладці «Зображення» додайте посилання на відео&lt;/li&gt;&lt;li&gt;3️⃣ Збережіть товар і перевірте галерею на вітрині&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Таблиці відео за замовчуванням не видаляються під час видалення модуля, щоб не втратити дані.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ YouTube · Vimeo · TikTok&lt;/li&gt;&lt;li&gt;✅ VideoObject JSON-LD&lt;/li&gt;&lt;li&gt;✅ UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Video Gallery PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Video Gallery PRO показує відео YouTube, Vimeo, TikTok, Facebook, Rutube, VK і OK просто в галереї товару, покращуючи картку й SEO.' WHERE `product_id`=101 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Video Gallery PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Video Gallery PRO&lt;/strong&gt; shows YouTube, Vimeo, TikTok, Facebook, Rutube, VK and OK videos right in the product gallery, improving the page and its SEO.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Videos in the product gallery: YouTube, Vimeo, TikTok, Facebook, Rutube, VK, OK&lt;/li&gt;&lt;li&gt;✅ Videos are stored in the database, not in a cache; final saving uses the standard product Save button&lt;/li&gt;&lt;li&gt;✅ YouTube iframe normalization in product descriptions: embed URL, title, allow and allowfullscreen&lt;/li&gt;&lt;li&gt;✅ A single VideoObject JSON-LD for gallery videos and YouTube in the description — no duplicates&lt;/li&gt;&lt;li&gt;✅ External thumbnails are cached locally and served through image/cache&lt;/li&gt;&lt;li&gt;✅ Soft integration with the default theme, UniShop2 and CodeCart PRO Theme&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Enable the module and check the providers&lt;/li&gt;&lt;li&gt;2️⃣ On the product Images tab, add a video link&lt;/li&gt;&lt;li&gt;3️⃣ Save the product and check the gallery on the storefront&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Video tables are not removed by default when the module is uninstalled, so no data is lost.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ YouTube · Vimeo · TikTok&lt;/li&gt;&lt;li&gt;✅ VideoObject JSON-LD&lt;/li&gt;&lt;li&gt;✅ UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Video Gallery PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Video Gallery PRO shows YouTube, Vimeo, TikTok, Facebook, Rutube, VK and OK videos right in the product gallery, improving the page and its SEO.' WHERE `product_id`=101 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Video Gallery PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Video Gallery PRO&lt;/strong&gt; показывает видео YouTube, Vimeo, TikTok, Facebook, Rutube, VK и OK прямо в галерее товара, улучшая карточку и SEO.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Видео в галерее товара: YouTube, Vimeo, TikTok, Facebook, Rutube, VK, OK&lt;/li&gt;&lt;li&gt;✅ Видео хранятся в базе данных, а не в кеше; финальное сохранение — штатной кнопкой «Сохранить» товара&lt;/li&gt;&lt;li&gt;✅ Нормализация YouTube iframe в описании товара: embed URL, title, allow и allowfullscreen&lt;/li&gt;&lt;li&gt;✅ Единый VideoObject JSON-LD для видео галереи и YouTube из описания — без дублей&lt;/li&gt;&lt;li&gt;✅ Внешние миниатюры кешируются локально и отдаются через image/cache&lt;/li&gt;&lt;li&gt;✅ Мягкая интеграция со стандартной темой, UniShop2 и CodeCart PRO Theme&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Включите модуль и проверьте провайдеров&lt;/li&gt;&lt;li&gt;2️⃣ В карточке товара на вкладке «Изображения» добавьте ссылку на видео&lt;/li&gt;&lt;li&gt;3️⃣ Сохраните товар и проверьте галерею на витрине&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Таблицы видео по умолчанию не удаляются при удалении модуля, чтобы не потерять данные.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ YouTube · Vimeo · TikTok&lt;/li&gt;&lt;li&gt;✅ VideoObject JSON-LD&lt;/li&gt;&lt;li&gt;✅ UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Video Gallery PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Video Gallery PRO показывает видео YouTube, Vimeo, TikTok, Facebook, Rutube, VK и OK прямо в галерее товара, улучшая карточку и SEO.' WHERE `product_id`=101 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Stats PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Stats PRO&lt;/strong&gt; показує в адмінці компактну клікабельну статистику цілісності каталогу й за кліком відкриває стандартний список товарів із потрібним серверним фільтром.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Увімкнені та вимкнені товари; увімкнені товари із залишком нуль або менше; від’ємний залишок&lt;/li&gt;&lt;li&gt;✅ Відсутній SEO URL, ціна нуль або менше, ознака доставки&lt;/li&gt;&lt;li&gt;✅ Проблеми зображення: порожнє, небезпечне, видалене або нечитабельне головне фото&lt;/li&gt;&lt;li&gt;✅ Немає виробника або його видалено; немає коректних категорій, немає головної категорії, конфлікт кількох головних&lt;/li&gt;&lt;li&gt;✅ Заповненість SKU, UPC, EAN, JAN, ISBN, MPN, розташування, податкового класу, розмірів і ваги; кожен показник можна приховати&lt;/li&gt;&lt;li&gt;✅ Аудит розмірів фото окремим блоком: невеликі AJAX-пакети по 40 товарів, мінімальні ширина й висота налаштовуються (за замовчуванням 500×500)&lt;/li&gt;&lt;li&gt;✅ Бічний блок займає місце штатної статистики замовлень; за вимкнення штатна статистика повертається&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Увімкніть модуль і оберіть показники&lt;/li&gt;&lt;li&gt;2️⃣ Клікніть на проблему — відкриється список товарів із фільтром&lt;/li&gt;&lt;li&gt;3️⃣ Запустіть аудит фото й виправте знайдені проблеми&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Перевірка розмірів фото виконується окремим запуском, а не за кожного відкриття каталогу.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Клік → фільтр&lt;/li&gt;&lt;li&gt;✅ Аудит фото&lt;/li&gt;&lt;li&gt;✅ Пакети по 40&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Stats PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Stats PRO показує в адмінці компактну клікабельну статистику цілісності каталогу й за кліком відкриває стандартний список товарів із потрібним…' WHERE `product_id`=102 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Stats PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Stats PRO&lt;/strong&gt; shows compact, clickable catalog-integrity statistics in the admin and opens the standard product list with the matching server-side filter on click.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Enabled and disabled products; enabled products with zero or lower stock; negative stock&lt;/li&gt;&lt;li&gt;✅ Missing SEO URL, price of zero or less, the shipping flag&lt;/li&gt;&lt;li&gt;✅ Image problems: an empty, unsafe, removed or unreadable main image&lt;/li&gt;&lt;li&gt;✅ Missing or deleted manufacturer; no valid categories, no main category, conflicting main categories&lt;/li&gt;&lt;li&gt;✅ Completeness of SKU, UPC, EAN, JAN, ISBN, MPN, location, tax class, dimensions and weight; each metric can be hidden&lt;/li&gt;&lt;li&gt;✅ A separate photo-size audit: small AJAX batches of 40 products, configurable minimum width and height (default 500×500)&lt;/li&gt;&lt;li&gt;✅ The side block takes the place of the stock order statistics; when disabled the stock statistics return&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Enable the module and choose the metrics&lt;/li&gt;&lt;li&gt;2️⃣ Click a problem — the product list opens with the filter applied&lt;/li&gt;&lt;li&gt;3️⃣ Run the photo audit and fix what it finds&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ The photo-size check runs as a separate action, not every time the catalog opens.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Click → filter&lt;/li&gt;&lt;li&gt;✅ Photo audit&lt;/li&gt;&lt;li&gt;✅ Batches of 40&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Stats PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Stats PRO shows compact, clickable catalog-integrity statistics in the admin and opens the standard product list with the matching server-side filter…' WHERE `product_id`=102 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Stats PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Stats PRO&lt;/strong&gt; показывает в админке компактную кликабельную статистику целостности каталога и по клику открывает стандартный список товаров с нужным серверным фильтром.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Включённые и отключённые товары; включённые товары с остатком ноль или меньше; отрицательный остаток&lt;/li&gt;&lt;li&gt;✅ Отсутствующий SEO URL, цена ноль или меньше, признак доставки&lt;/li&gt;&lt;li&gt;✅ Проблемы изображения: пустое, небезопасное, удалённое или нечитаемое главное фото&lt;/li&gt;&lt;li&gt;✅ Нет производителя или он удалён; нет корректных категорий, нет главной категории, конфликт нескольких главных&lt;/li&gt;&lt;li&gt;✅ Заполненность SKU, UPC, EAN, JAN, ISBN, MPN, расположения, налогового класса, размеров и веса; каждый показатель можно скрыть&lt;/li&gt;&lt;li&gt;✅ Аудит размеров фото отдельным блоком: небольшие AJAX-пакеты по 40 товаров, минимальные ширина и высота настраиваются (по умолчанию 500×500)&lt;/li&gt;&lt;li&gt;✅ Боковой блок занимает место штатной статистики заказов; при отключении штатная статистика возвращается&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Включите модуль и выберите показатели&lt;/li&gt;&lt;li&gt;2️⃣ Кликните на проблему — откроется список товаров с фильтром&lt;/li&gt;&lt;li&gt;3️⃣ Запустите аудит фото и исправьте найденные проблемы&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Проверка размеров фото выполняется отдельным запуском, а не при каждом открытии каталога.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Клик → фильтр&lt;/li&gt;&lt;li&gt;✅ Аудит фото&lt;/li&gt;&lt;li&gt;✅ Пакеты по 40&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Stats PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Stats PRO показывает в админке компактную кликабельную статистику целостности каталога и по клику открывает стандартный список товаров с нужным…' WHERE `product_id`=102 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Unit PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Unit PRO&lt;/strong&gt; додає до товару одиницю продажу біля ціни й, за потреби, справжній дробовий продаж: 0,5 кг, 1,2 м, 2,75 л, 3,5 пог. м тощо.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Одиниці трьома мовами: шт., м, пог. м, л, мл, кг, г, м², м³, уп., рулон, комплект, набір, пара, мішок, каністра; власна багатомовна одиниця й підпис біля ціни&lt;/li&gt;&lt;li&gt;✅ Дробовий продаж для кожного товару окремо: крок кількості (0,1; 0,25; 0,5), мінімальна кількість&lt;/li&gt;&lt;li&gt;✅ Стандартний шаблон підтримується через штатні механізми Cart, Order і Product; для UniShop2 є окремий bridge для швидкого замовлення, міні-кошика й UniCheckout&lt;/li&gt;&lt;li&gt;✅ Звичайні товари й далі працюють із цілою кількістю та стандартною логікою OpenCart&lt;/li&gt;&lt;li&gt;✅ Після встановлення вимкнений; одиниця та дробовий продаж за замовчуванням відключені&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Увімкніть модуль і дозвольте дробовий продаж глобально&lt;/li&gt;&lt;li&gt;2️⃣ У картці товару оберіть одиницю й крок кількості&lt;/li&gt;&lt;li&gt;3️⃣ Перевірте кошик і оформлення замовлення&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Якщо у сторонньої теми власний checkout і вона приводить кількість до цілого, знадобиться невеликий додатковий bridge.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Дробові кількості&lt;/li&gt;&lt;li&gt;✅ Одиниці виміру&lt;/li&gt;&lt;li&gt;✅ UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Unit PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Unit PRO додає до товару одиницю продажу біля ціни й, за потреби, справжній дробовий продаж: 0,5 кг, 1,2 м, 2,75 л, 3,5 пог. м тощо.' WHERE `product_id`=103 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Unit PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Unit PRO&lt;/strong&gt; adds a sales unit next to the price and, when needed, real fractional selling: 0.5 kg, 1.2 m, 2.75 l, 3.5 running m and so on.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Units in three languages: pcs, m, running m, l, ml, kg, g, m², m³, pack, roll, set, kit, pair, bag, canister; a custom multilingual unit and a label next to the price&lt;/li&gt;&lt;li&gt;✅ Fractional selling per product: quantity step (0.1, 0.25, 0.5) and minimum quantity&lt;/li&gt;&lt;li&gt;✅ The default template works through standard Cart, Order and Product mechanisms; UniShop2 has a separate bridge for Quick Order, mini-cart and UniCheckout&lt;/li&gt;&lt;li&gt;✅ Ordinary products keep using whole quantities and the standard OpenCart logic&lt;/li&gt;&lt;li&gt;✅ Off after installation; the unit and fractional selling are disabled by default&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Enable the module and allow fractional selling globally&lt;/li&gt;&lt;li&gt;2️⃣ Choose the unit and quantity step on the product page&lt;/li&gt;&lt;li&gt;3️⃣ Check the cart and checkout&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ If a third-party theme has its own checkout and casts quantity to an integer, a small additional bridge is needed.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Fractional quantities&lt;/li&gt;&lt;li&gt;✅ Units of measure&lt;/li&gt;&lt;li&gt;✅ UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Three-language interface&lt;/h3&gt;&lt;p&gt;The module admin is available in Russian, Ukrainian and English — convenient for stores and teams working in different language environments.&lt;/p&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Unit PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Unit PRO adds a sales unit next to the price and, when needed, real fractional selling: 0.5 kg, 1.2 m, 2.75 l, 3.5 running m and so on.' WHERE `product_id`=103 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Unit PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Unit PRO&lt;/strong&gt; добавляет к товару единицу продажи возле цены и, при необходимости, настоящую дробную продажу: 0,5 кг, 1,2 м, 2,75 л, 3,5 пог. м и так далее.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Единицы на трёх языках: шт., м, пог. м, л, мл, кг, г, м², м³, уп., рулон, комплект, набор, пара, мешок, канистра; собственная многоязычная единица и подпись возле цены&lt;/li&gt;&lt;li&gt;✅ Дробная продажа для каждого товара отдельно: шаг количества (0,1; 0,25; 0,5), минимальное количество&lt;/li&gt;&lt;li&gt;✅ Стандартный шаблон поддерживается через штатные механизмы Cart, Order и Product; для UniShop2 есть отдельный bridge для быстрого заказа, мини-корзины и UniCheckout&lt;/li&gt;&lt;li&gt;✅ Обычные товары продолжают работать с целым количеством и стандартной логикой OpenCart&lt;/li&gt;&lt;li&gt;✅ После установки выключен; единица и дробная продажа по умолчанию отключены&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Включите модуль и разрешите дробную продажу глобально&lt;/li&gt;&lt;li&gt;2️⃣ В карточке товара выберите единицу и шаг количества&lt;/li&gt;&lt;li&gt;3️⃣ Проверьте корзину и оформление заказа&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Если у сторонней темы собственный checkout и она приводит количество к целому, потребуется небольшой дополнительный bridge.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Дробные количества&lt;/li&gt;&lt;li&gt;✅ Единицы измерения&lt;/li&gt;&lt;li&gt;✅ UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Unit PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Unit PRO добавляет к товару единицу продажи возле цены и, при необходимости, настоящую дробную продажу: 0,5 кг, 1,2 м, 2,75 л, 3,5 пог. м и так далее.' WHERE `product_id`=103 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Manager PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Manager PRO&lt;/strong&gt; — єдиний центр керування товарами для ocStore 3.0.4.1 та OpenCart 3.x: швидко редагувати, перевіряти повноту карток, SEO, зображення, маржу, категорії, атрибути й технічні помилки без постійного відкривання кожної картки.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Швидке редагування товарів і масові дії з попереднім переглядом&lt;/li&gt;&lt;li&gt;✅ Пошук слабких карток і SEO-проблем&lt;/li&gt;&lt;li&gt;✅ Контроль головних і додаткових зображень: биті, важкі, малі та повторювані; перевірка кешу, WebP, AVIF, alt і SEO-імені файла&lt;/li&gt;&lt;li&gt;✅ Маржа й собівартість, категорії та атрибути&lt;/li&gt;&lt;li&gt;✅ Режим «лише аудит» для безпечної діагностики; історія змін і відкат пакета&lt;/li&gt;&lt;li&gt;✅ Cron-черга для важких перевірок через захищений catalog endpoint із секретним ключем&lt;/li&gt;&lt;li&gt;✅ Експорт звітів, експорт та імпорт налаштувань, відновлення налаштувань за замовчуванням&lt;/li&gt;&lt;li&gt;✅ Усі небезпечні функції вимкнені за замовчуванням&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Увімкніть режим «лише аудит» і перегляньте звіти&lt;/li&gt;&lt;li&gt;2️⃣ Вмикайте масові дії в міру потреби — з попереднім переглядом&lt;/li&gt;&lt;li&gt;3️⃣ У разі помилки відкотіть пакет з історії&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Після встановлення модуль не змінює товари, не запускає аудит і не виконує cron до ручного вмикання налаштувань.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Аудит + масові дії&lt;/li&gt;&lt;li&gt;✅ Відкат пакета&lt;/li&gt;&lt;li&gt;✅ Cron-черга&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Manager PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Manager PRO — єдиний центр керування товарами для ocStore 3.0.4.1 та OpenCart 3.x: швидко редагувати, перевіряти повноту карток, SEO, зображення…' WHERE `product_id`=104 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Manager PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Manager PRO&lt;/strong&gt; is a single control center for products in ocStore 3.0.4.1 and OpenCart 3.x: edit quickly and check card completeness, SEO, images, margin, categories, attributes and technical errors without opening every product page.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Quick product editing and bulk actions with a preview&lt;/li&gt;&lt;li&gt;✅ Finds weak product cards and SEO problems&lt;/li&gt;&lt;li&gt;✅ Control of main and extra images: broken, heavy, small and duplicated; checks of cache, WebP, AVIF, alt and the SEO file name&lt;/li&gt;&lt;li&gt;✅ Margin and cost price, categories and attributes&lt;/li&gt;&lt;li&gt;✅ An audit-only mode for safe diagnostics; change history and batch rollback&lt;/li&gt;&lt;li&gt;✅ A cron queue for heavy checks through a protected catalog endpoint with a secret key&lt;/li&gt;&lt;li&gt;✅ Report export, settings export and import, restoring default settings&lt;/li&gt;&lt;li&gt;✅ All dangerous functions are off by default&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Enable audit-only mode and look at the reports&lt;/li&gt;&lt;li&gt;2️⃣ Enable bulk actions as needed — with a preview&lt;/li&gt;&lt;li&gt;3️⃣ Roll back a batch from the history if something goes wrong&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ After installation the module changes no products, runs no audit and no cron until you enable the settings manually.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Audit + bulk actions&lt;/li&gt;&lt;li&gt;✅ Batch rollback&lt;/li&gt;&lt;li&gt;✅ Cron queue&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Manager PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Manager PRO is a single control center for products in ocStore 3.0.4.1 and OpenCart 3.x: edit quickly and check card completeness, SEO, images…' WHERE `product_id`=104 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Product Manager PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Product Manager PRO&lt;/strong&gt; — единый центр управления товарами для ocStore 3.0.4.1 и OpenCart 3.x: быстро редактировать, проверять полноту карточек, SEO, изображения, маржу, категории, атрибуты и технические ошибки без постоянного открытия каждой карточки.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Быстрое редактирование товаров и массовые действия с предпросмотром&lt;/li&gt;&lt;li&gt;✅ Поиск слабых карточек и SEO-проблем&lt;/li&gt;&lt;li&gt;✅ Контроль главных и дополнительных изображений: битые, тяжёлые, маленькие и повторяющиеся; проверка кеша, WebP, AVIF, alt и SEO-имени файла&lt;/li&gt;&lt;li&gt;✅ Маржа и себестоимость, категории и атрибуты&lt;/li&gt;&lt;li&gt;✅ Режим «только аудит» для безопасной диагностики; история изменений и откат пакета&lt;/li&gt;&lt;li&gt;✅ Cron-очередь для тяжёлых проверок через защищённый catalog endpoint с секретным ключом&lt;/li&gt;&lt;li&gt;✅ Экспорт отчётов, экспорт и импорт настроек, восстановление настроек по умолчанию&lt;/li&gt;&lt;li&gt;✅ Все опасные функции выключены по умолчанию&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Включите режим «только аудит» и посмотрите отчёты&lt;/li&gt;&lt;li&gt;2️⃣ Включайте массовые действия по мере необходимости — с предпросмотром&lt;/li&gt;&lt;li&gt;3️⃣ При ошибке откатите пакет из истории&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ После установки модуль не меняет товары, не запускает аудит и не выполняет cron до ручного включения настроек.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Аудит + массовые действия&lt;/li&gt;&lt;li&gt;✅ Откат пакета&lt;/li&gt;&lt;li&gt;✅ Cron-очередь&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Product Manager PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Product Manager PRO — единый центр управления товарами для ocStore 3.0.4.1 и OpenCart 3.x: быстро редактировать, проверять полноту карточек, SEO…' WHERE `product_id`=104 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Popup Banner PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Popup Banner PRO&lt;/strong&gt; — менеджер рекламних popup-кампаній із таргетингом за сторінками, категоріями, товарами, мовами, пристроями та поведінкою відвідувача.&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Зображення відокремлене від редагованого тексту, тому одна кампанія коректно працює на всіх мовах і екранах.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Незалежні кампанії з розкладом&lt;/li&gt;&lt;li&gt;✅ Таргетинг: сторінки, категорії, товари, мова, пристрій, поведінка відвідувача&lt;/li&gt;&lt;li&gt;✅ Обмеження за підсумком кошика в базовій валюті магазину&lt;/li&gt;&lt;li&gt;✅ Змінні PRODUCT_NAME, PRICE, SPECIAL_PRICE і CATEGORY_NAME обчислюються лише там, де використовуються&lt;/li&gt;&lt;li&gt;✅ Вбудований банк оптимізованих універсальних візуалів без тексту (знижка, доставка, новинка, подарунок, консультація, графік, техроботи, магазин зачинено)&lt;/li&gt;&lt;li&gt;✅ Зображення можна призначати окремо для ПК, планшета й мобільного&lt;/li&gt;&lt;li&gt;✅ Текст локалізується й повністю редагується&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Створіть кампанію й оберіть візуал із банку або завантажте свій&lt;/li&gt;&lt;li&gt;2️⃣ Задайте тексти за мовами та умови показу&lt;/li&gt;&lt;li&gt;3️⃣ Увімкніть розклад і перевірте на різних пристроях&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Для роботи потрібна активна ліцензія PRO.&lt;/li&gt;&lt;li&gt;✅ Не зловживайте частотою показу — це впливає на зручність покупців.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Таргетинг&lt;/li&gt;&lt;li&gt;✅ Розклад&lt;/li&gt;&lt;li&gt;✅ UA · RU · EN&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Інтерфейс трьома мовами&lt;/h3&gt;&lt;p&gt;Адмінка модуля доступна російською, українською та англійською мовами — зручно для магазинів і команд, які працюють у різних мовних середовищах.&lt;/p&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Popup Banner PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Popup Banner PRO — менеджер рекламних popup-кампаній із таргетингом за сторінками, категоріями, товарами, мовами, пристроями та поведінкою відвідувача.…' WHERE `product_id`=105 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Popup Banner PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Popup Banner PRO&lt;/strong&gt; is a manager of promotional popup campaigns targeted by page, category, product, language, device and visitor behavior.&lt;/p&gt;&lt;h3&gt;💡 Why you need it&lt;/h3&gt;&lt;p&gt;The visual is separate from editable text, so one campaign works correctly on every language and screen.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Independent campaigns with a schedule&lt;/li&gt;&lt;li&gt;✅ Targeting: pages, categories, products, language, device, visitor behavior&lt;/li&gt;&lt;li&gt;✅ Conditions on the cart subtotal in the store’s base currency&lt;/li&gt;&lt;li&gt;✅ PRODUCT_NAME, PRICE, SPECIAL_PRICE and CATEGORY_NAME are evaluated only where they are used&lt;/li&gt;&lt;li&gt;✅ Built-in bank of optimized, text-free universal visuals (discount, delivery, new, gift, consultation, hours, maintenance, store closed)&lt;/li&gt;&lt;li&gt;✅ Images can be assigned separately for desktop, tablet and mobile&lt;/li&gt;&lt;li&gt;✅ Text is localized and fully editable&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Create a campaign and pick a visual from the bank or upload your own&lt;/li&gt;&lt;li&gt;2️⃣ Set texts per language and display conditions&lt;/li&gt;&lt;li&gt;3️⃣ Enable the schedule and test on different devices&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ An active PRO license is required.&lt;/li&gt;&lt;li&gt;✅ Do not overuse display frequency — it affects shopper comfort.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Targeting&lt;/li&gt;&lt;li&gt;✅ Schedule&lt;/li&gt;&lt;li&gt;✅ UA · RU · EN&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Three-language interface&lt;/h3&gt;&lt;p&gt;The module admin is available in Russian, Ukrainian and English — convenient for stores and teams working in different language environments.&lt;/p&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Popup Banner PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Popup Banner PRO is a manager of promotional popup campaigns targeted by page, category, product, language, device and visitor behavior. The visual is…' WHERE `product_id`=105 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Popup Banner PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Popup Banner PRO&lt;/strong&gt; — менеджер рекламных popup-кампаний с таргетингом по страницам, категориям, товарам, языкам, устройствам и поведению посетителя.&lt;/p&gt;&lt;h3&gt;💡 Зачем нужен модуль&lt;/h3&gt;&lt;p&gt;Картинка отделена от редактируемого текста, поэтому одна кампания корректно работает на всех языках и экранах.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Независимые кампании с расписанием&lt;/li&gt;&lt;li&gt;✅ Таргетинг: страницы, категории, товары, язык, устройство, поведение посетителя&lt;/li&gt;&lt;li&gt;✅ Ограничения по подытогу корзины в базовой валюте магазина&lt;/li&gt;&lt;li&gt;✅ Переменные PRODUCT_NAME, PRICE, SPECIAL_PRICE и CATEGORY_NAME вычисляются только там, где используются&lt;/li&gt;&lt;li&gt;✅ Встроенный банк оптимизированных универсальных визуалов без текста (скидка, доставка, новинка, подарок, консультация, график, техработы, магазин закрыт)&lt;/li&gt;&lt;li&gt;✅ Изображения можно назначать отдельно для ПК, планшета и мобильного&lt;/li&gt;&lt;li&gt;✅ Текст локализуется и полностью редактируется&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Создайте кампанию и выберите визуал из банка или загрузите свой&lt;/li&gt;&lt;li&gt;2️⃣ Задайте тексты по языкам и условия показа&lt;/li&gt;&lt;li&gt;3️⃣ Включите расписание и проверьте на разных устройствах&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Для работы требуется активная лицензия PRO.&lt;/li&gt;&lt;li&gt;✅ Не злоупотребляйте частотой показа — это влияет на удобство покупателей.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Таргетинг&lt;/li&gt;&lt;li&gt;✅ Расписание&lt;/li&gt;&lt;li&gt;✅ UA · RU · EN&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Интерфейс на трёх языках&lt;/h3&gt;&lt;p&gt;Админка модуля доступна на русском, украинском и английском языках — удобно для магазинов и команд, работающих в разных языковых средах.&lt;/p&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Popup Banner PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Popup Banner PRO — менеджер рекламных popup-кампаний с таргетингом по страницам, категориям, товарам, языкам, устройствам и поведению посетителя. Картинка…' WHERE `product_id`=105 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;PHP 8 Compatibility PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;PHP 8 Compatibility PRO&lt;/strong&gt; — адміністративний модуль діагностики й контрольованого виправлення сумісності OpenCart/ocStore 3.0.x під час переходу на PHP 7.4 baseline та PHP 8.1–8.5.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Аналіз ядра, розширень, PHP-коду тем, OCMOD, storage/modification, system/library, Composer/vendor і вкладених Composer-залежностей модулів&lt;/li&gt;&lt;li&gt;✅ Перевірка обов’язкових PHP-розширень, ionCube і SourceGuardian, runtime-логів&lt;/li&gt;&lt;li&gt;✅ Один повний прохід будує матрицю PHP 7.4 baseline + 8.1–8.5: у кожної проблеми вказано min_php&lt;/li&gt;&lt;li&gt;✅ Профіль версії ядра перевіряється окремо: версії до 3.0.4.x не сертифікуються вище PHP 8.3, 3.0.5.0 — вище 8.4, 3.0.5.1+ допускає профіль до 8.5&lt;/li&gt;&lt;li&gt;✅ Twig та інші Composer-пакети перевіряються за версією, PHP-обмеженням і ext-* залежностями; vendor автоматично не виправляється&lt;/li&gt;&lt;li&gt;✅ Контрольовані виправлення та інструкція аварійного відновлення&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Зробіть резервну копію та запустіть повний прохід&lt;/li&gt;&lt;li&gt;2️⃣ Оберіть цільову версію PHP у результатах і вивчіть знахідки&lt;/li&gt;&lt;li&gt;3️⃣ Виправте знайдене (зокрема контрольованими виправленнями) і перевірте на staging&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Локально виправлена збірка може працювати вище базової стелі ядра, але це підтверджується перевіркою на staging, а не звітом модуля.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ PHP 7.4 → 8.5&lt;/li&gt;&lt;li&gt;✅ Матриця знахідок&lt;/li&gt;&lt;li&gt;✅ Staging&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Інтерфейс трьома мовами&lt;/h3&gt;&lt;p&gt;Адмінка модуля доступна російською, українською та англійською мовами — зручно для магазинів і команд, які працюють у різних мовних середовищах.&lt;/p&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;PHP 8 Compatibility PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='PHP 8 Compatibility PRO — адміністративний модуль діагностики й контрольованого виправлення сумісності OpenCart/ocStore 3.0.x під час переходу на PHP 7.4…' WHERE `product_id`=106 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;PHP 8 Compatibility PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;PHP 8 Compatibility PRO&lt;/strong&gt; is an admin module for diagnosing and carefully fixing OpenCart/ocStore 3.0.x compatibility when moving to a PHP 7.4 baseline and PHP 8.1–8.5.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Analyzes the core, extensions, theme PHP code, OCMOD, storage/modification, system/library, Composer/vendor and the nested Composer dependencies of individual modules&lt;/li&gt;&lt;li&gt;✅ Checks required PHP extensions, ionCube and SourceGuardian and runtime logs&lt;/li&gt;&lt;li&gt;✅ One full pass builds a PHP 7.4 baseline + 8.1–8.5 matrix: every issue carries a min_php&lt;/li&gt;&lt;li&gt;✅ The core version profile is checked separately: versions before 3.0.4.x are not certified above PHP 8.3, 3.0.5.0 above 8.4, 3.0.5.1+ allows up to 8.5&lt;/li&gt;&lt;li&gt;✅ Twig and other Composer packages are checked by version, PHP constraint and ext-* dependencies; vendor is never fixed automatically&lt;/li&gt;&lt;li&gt;✅ Controlled fixes and an emergency recovery guide&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Back up and run a full pass&lt;/li&gt;&lt;li&gt;2️⃣ Pick the target PHP version in the results and review the findings&lt;/li&gt;&lt;li&gt;3️⃣ Fix what was found (including with controlled fixes) and verify on staging&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ A locally patched build can run above the core’s baseline ceiling, but that is confirmed by staging tests, not by the module’s report.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ PHP 7.4 → 8.5&lt;/li&gt;&lt;li&gt;✅ Findings matrix&lt;/li&gt;&lt;li&gt;✅ Staging&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Three-language interface&lt;/h3&gt;&lt;p&gt;The module admin is available in Russian, Ukrainian and English — convenient for stores and teams working in different language environments.&lt;/p&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;PHP 8 Compatibility PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='PHP 8 Compatibility PRO is an admin module for diagnosing and carefully fixing OpenCart/ocStore 3.0.x compatibility when moving to a PHP 7.4 baseline and PHP…' WHERE `product_id`=106 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;PHP 8 Compatibility PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;PHP 8 Compatibility PRO&lt;/strong&gt; — административный модуль диагностики и контролируемого исправления совместимости OpenCart/ocStore 3.0.x при переходе на PHP 7.4 baseline и PHP 8.1–8.5.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Анализ ядра, расширений, PHP-кода тем, OCMOD, storage/modification, system/library, Composer/vendor и вложенных Composer-зависимостей модулей&lt;/li&gt;&lt;li&gt;✅ Проверка обязательных PHP-расширений, ionCube и SourceGuardian, runtime-логов&lt;/li&gt;&lt;li&gt;✅ Один полный проход строит матрицу PHP 7.4 baseline + 8.1–8.5: у каждой проблемы указан min_php&lt;/li&gt;&lt;li&gt;✅ Профиль версии ядра проверяется отдельно: версии до 3.0.4.x не сертифицируются выше PHP 8.3, 3.0.5.0 — выше 8.4, 3.0.5.1+ допускает профиль до 8.5&lt;/li&gt;&lt;li&gt;✅ Twig и другие Composer-пакеты проверяются по версии, PHP-ограничению и ext-* зависимостям; vendor автоматически не исправляется&lt;/li&gt;&lt;li&gt;✅ Контролируемые исправления и инструкция аварийного восстановления&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Сделайте резервную копию и запустите полный проход&lt;/li&gt;&lt;li&gt;2️⃣ Выберите целевую версию PHP в результатах и изучите находки&lt;/li&gt;&lt;li&gt;3️⃣ Исправьте найденное (в том числе контролируемыми исправлениями) и проверьте на staging&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Локально исправленная сборка может работать выше базового потолка ядра, но это подтверждается проверкой на staging, а не отчётом модуля.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ PHP 7.4 → 8.5&lt;/li&gt;&lt;li&gt;✅ Матрица находок&lt;/li&gt;&lt;li&gt;✅ Staging&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Интерфейс на трёх языках&lt;/h3&gt;&lt;p&gt;Админка модуля доступна на русском, украинском и английском языках — удобно для магазинов и команд, работающих в разных языковых средах.&lt;/p&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;PHP 8 Compatibility PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='PHP 8 Compatibility PRO — административный модуль диагностики и контролируемого исправления совместимости OpenCart/ocStore 3.0.x при переходе на PHP 7.4…' WHERE `product_id`=106 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Option Price Equal Prefix PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Option Price Equal Prefix PRO&lt;/strong&gt; додає значенням опцій третій варіант ціни: поруч зі стандартними «+» і «−» з’являється «=».&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Обрана опція з «=» замінює базову ціну товару — зручно для варіантів з відомою підсумковою вартістю.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Префікс «=» для ціни значення опції&lt;/li&gt;&lt;li&gt;✅ Обране значення замінює базову ціну товару&lt;/li&gt;&lt;li&gt;✅ Стандартні «+» і «−» інших опцій продовжують працювати відносно нової бази&lt;/li&gt;&lt;li&gt;✅ Дані опцій залишаються в OpenCart і не видаляються при зніманні модифікатора&lt;/li&gt;&lt;li&gt;✅ Підходить для розмірів, комплектацій і варіантів із готовою ціною&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Встановіть модуль і оновіть модифікатори&lt;/li&gt;&lt;li&gt;2️⃣ В опції товару оберіть префікс «=» і введіть підсумкову ціну&lt;/li&gt;&lt;li&gt;3️⃣ Перевірте перерахунок ціни в картці та кошику&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Якщо обрано кілька «=», базою стає остання оброблена; використовуйте «=» в одній взаємовиключній групі опцій.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Опції&lt;/li&gt;&lt;li&gt;✅ Префікс =&lt;/li&gt;&lt;li&gt;✅ OCMOD&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Option Price Equal Prefix PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Option Price Equal Prefix PRO додає значенням опцій третій варіант ціни: поруч зі стандартними «+» і «−» з’являється «=». Обрана опція з «=» замінює базову…' WHERE `product_id`=107 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Option Price Equal Prefix PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Option Price Equal Prefix PRO&lt;/strong&gt; gives option values a third price mode: next to the standard “+” and “−” there is “=”.&lt;/p&gt;&lt;h3&gt;💡 Why you need it&lt;/h3&gt;&lt;p&gt;A selected option with “=” replaces the product’s base price — ideal for variants with a known final price.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ “=” prefix for option value price&lt;/li&gt;&lt;li&gt;✅ The selected value replaces the product base price&lt;/li&gt;&lt;li&gt;✅ Standard “+” and “−” of other options still apply on top of the new base&lt;/li&gt;&lt;li&gt;✅ Option data stays in OpenCart and is not deleted if the modification is removed&lt;/li&gt;&lt;li&gt;✅ Fits sizes, bundles and variants with a ready price&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Install the module and refresh modifications&lt;/li&gt;&lt;li&gt;2️⃣ In the product option choose the “=” prefix and enter the final price&lt;/li&gt;&lt;li&gt;3️⃣ Check the recalculation in the product card and cart&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ If several “=” values are selected, the last one processed becomes the base; use “=” within one mutually exclusive option group.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Options&lt;/li&gt;&lt;li&gt;✅ “=” prefix&lt;/li&gt;&lt;li&gt;✅ OCMOD&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Option Price Equal Prefix PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Option Price Equal Prefix PRO gives option values a third price mode: next to the standard “+” and “−” there is “=”. A selected option with “=” replaces the…' WHERE `product_id`=107 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Option Price Equal Prefix PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Option Price Equal Prefix PRO&lt;/strong&gt; добавляет значениям опций третий вариант цены: рядом со стандартными «+» и «−» появляется «=».&lt;/p&gt;&lt;h3&gt;💡 Зачем нужен модуль&lt;/h3&gt;&lt;p&gt;Выбранная опция с «=» заменяет базовую цену товара — удобно для вариантов с известной итоговой стоимостью.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Префикс «=» для цены значения опции&lt;/li&gt;&lt;li&gt;✅ Выбранное значение заменяет базовую цену товара&lt;/li&gt;&lt;li&gt;✅ Стандартные «+» и «−» других опций продолжают работать относительно новой базы&lt;/li&gt;&lt;li&gt;✅ Данные опций остаются в OpenCart и не удаляются при снятии модификатора&lt;/li&gt;&lt;li&gt;✅ Подходит для размеров, комплектаций и вариантов с готовой ценой&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Установите модуль и обновите модификаторы&lt;/li&gt;&lt;li&gt;2️⃣ В опции товара выберите префикс «=» и введите итоговую цену&lt;/li&gt;&lt;li&gt;3️⃣ Проверьте пересчёт цены в карточке и корзине&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Если выбрано несколько «=», базой становится последняя обработанная; используйте «=» в одной взаимоисключающей группе опций.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Опции&lt;/li&gt;&lt;li&gt;✅ Префикс =&lt;/li&gt;&lt;li&gt;✅ OCMOD&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Option Price Equal Prefix PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Option Price Equal Prefix PRO добавляет значениям опций третий вариант цены: рядом со стандартными «+» и «−» появляется «=». Выбранная опция с «=» заменяет…' WHERE `product_id`=107 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Option Manager PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Option Manager PRO&lt;/strong&gt; керує саме опціями OpenCart/ocStore — колір, розмір, довжина, комплектація, напруга, тип роз’єму й інші варіанти, що впливають на ціну, залишок, вагу та кошик.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Повноцінний редактор опцій і їхніх значень із перетягуванням і збереженням порядку&lt;/li&gt;&lt;li&gt;✅ Шаблони опцій: required, значення, кількість, subtract, ціна, бали, вага та порядок&lt;/li&gt;&lt;li&gt;✅ Масове застосування шаблону до товарів із попереднім переглядом: додати відсутні, замінити всі опції або оновити збіжні&lt;/li&gt;&lt;li&gt;✅ Пошук точних і схожих дублів опцій і значень; безпечне об’єднання з попереднім переглядом&lt;/li&gt;&lt;li&gt;✅ Масові дії за обраними опціями; CSV-експорт та імпорт опцій і значень із зображеннями&lt;/li&gt;&lt;li&gt;✅ Вставлення шаблону просто в картці товару без AJAX-збереження товару&lt;/li&gt;&lt;li&gt;✅ Підказки, вкладка допомоги, діагностика&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Створіть шаблон опцій&lt;/li&gt;&lt;li&gt;2️⃣ Застосуйте його до потрібних товарів через вкладку «Застосувати до товарів» із попереднім переглядом&lt;/li&gt;&lt;li&gt;3️⃣ Знайдіть і об’єднайте дублі опцій і значень&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Дані опцій товару через панель у картці зберігаються лише штатною кнопкою «Зберегти».&lt;/li&gt;&lt;li&gt;✅ Об’єднання опцій вмикайте після резервної копії.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Шаблони опцій&lt;/li&gt;&lt;li&gt;✅ Злиття дублів&lt;/li&gt;&lt;li&gt;✅ CSV&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Option Manager PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Option Manager PRO керує саме опціями OpenCart/ocStore — колір, розмір, довжина, комплектація, напруга, тип роз’єму й інші варіанти, що впливають на ціну…' WHERE `product_id`=108 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Option Manager PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Option Manager PRO&lt;/strong&gt; manages OpenCart/ocStore options — color, size, length, bundle, voltage, connector type and other variants that affect price, stock, weight and the cart.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ A full editor for options and option values with drag-and-drop and saved order&lt;/li&gt;&lt;li&gt;✅ Option templates: required, values, quantity, subtract, price, points, weight and order&lt;/li&gt;&lt;li&gt;✅ Bulk template application to products with a preview: add missing, replace all options or update matching&lt;/li&gt;&lt;li&gt;✅ Search for exact and similar duplicate options and values; safe merging with a preview&lt;/li&gt;&lt;li&gt;✅ Bulk actions on selected options; CSV export and import of options and values with images&lt;/li&gt;&lt;li&gt;✅ Insert a template right on the product page without AJAX-saving the product&lt;/li&gt;&lt;li&gt;✅ Hints, a help tab and diagnostics&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Create an option template&lt;/li&gt;&lt;li&gt;2️⃣ Apply it to products on the “Apply to products” tab with a preview&lt;/li&gt;&lt;li&gt;3️⃣ Find and merge duplicate options and values&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Option data entered through the product panel is saved only with the standard Save button.&lt;/li&gt;&lt;li&gt;✅ Enable option merging after a backup.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Option templates&lt;/li&gt;&lt;li&gt;✅ Duplicate merge&lt;/li&gt;&lt;li&gt;✅ CSV&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🌍 Three-language interface&lt;/h3&gt;&lt;p&gt;The module admin is available in Russian, Ukrainian and English — convenient for stores and teams working in different language environments.&lt;/p&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Option Manager PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Option Manager PRO manages OpenCart/ocStore options — color, size, length, bundle, voltage, connector type and other variants that affect price, stock…' WHERE `product_id`=108 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Option Manager PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Option Manager PRO&lt;/strong&gt; управляет именно опциями OpenCart/ocStore — цвет, размер, длина, комплектация, напряжение, тип разъёма и другими вариантами, влияющими на цену, остаток, вес и корзину.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Полноценный редактор опций и их значений с перетаскиванием и сохранением порядка&lt;/li&gt;&lt;li&gt;✅ Шаблоны опций: required, значения, количество, subtract, цена, баллы, вес и порядок&lt;/li&gt;&lt;li&gt;✅ Массовое применение шаблона к товарам с предпросмотром: добавить недостающие, заменить все опции или обновить совпадающие&lt;/li&gt;&lt;li&gt;✅ Поиск точных и похожих дублей опций и значений; безопасное объединение с предпросмотром&lt;/li&gt;&lt;li&gt;✅ Массовые действия по выбранным опциям; CSV-экспорт и импорт опций и значений с изображениями&lt;/li&gt;&lt;li&gt;✅ Вставка шаблона прямо в карточке товара без AJAX-сохранения товара&lt;/li&gt;&lt;li&gt;✅ Подсказки, вкладка помощи, диагностика&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Создайте шаблон опций&lt;/li&gt;&lt;li&gt;2️⃣ Примените его к нужным товарам через вкладку «Применить к товарам» с предпросмотром&lt;/li&gt;&lt;li&gt;3️⃣ Найдите и объедините дубли опций и значений&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Данные опций товара через панель в карточке сохраняются только штатной кнопкой «Сохранить».&lt;/li&gt;&lt;li&gt;✅ Объединение опций включайте после резервной копии.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Шаблоны опций&lt;/li&gt;&lt;li&gt;✅ Слияние дублей&lt;/li&gt;&lt;li&gt;✅ CSV&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Option Manager PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Option Manager PRO управляет именно опциями OpenCart/ocStore — цвет, размер, длина, комплектация, напряжение, тип разъёма и другими вариантами, влияющими на…' WHERE `product_id`=108 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;New Year Decor PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;New Year Decor PRO&lt;/strong&gt; додає на вітрину легке святкове оформлення: гірлянди та сніг на Canvas.&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Ефекти не зачіпають товари, кошик, ціни та SEO, а при вимкненні модуль не підключає ні CSS, ні JS, ні HTML.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Інтерактивна гірлянда з іграшками та класична світлова гірлянда&lt;/li&gt;&lt;li&gt;✅ П’ять графічних варіантів гірлянди на одному безшовному локальному WebP-тайлі&lt;/li&gt;&lt;li&gt;✅ Два варіанти «Свято» без ялинки — для днів народження й акцій упродовж року&lt;/li&gt;&lt;li&gt;✅ Легкий сніг на Canvas, режим «Власна WebP-сніжинка» з прозорим зображенням&lt;/li&gt;&lt;li&gt;✅ Ефекти вмикаються окремо або разом&lt;/li&gt;&lt;li&gt;✅ Не змінює товари, оформлення замовлення, зображення, кеш, SEO, ціни, валюти й замовлення&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Встановіть і активуйте ліцензію&lt;/li&gt;&lt;li&gt;2️⃣ Оберіть гірлянду й сніг&lt;/li&gt;&lt;li&gt;3️⃣ Увімкніть модуль на період свят&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Без активної ліцензії статус залишається вимкненим.&lt;/li&gt;&lt;li&gt;✅ Вимикайте оформлення після свят.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;li&gt;✅ Роботу модуля можна переглянути в демо-адмінці до купівлі.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, зокрема 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Гірлянди&lt;/li&gt;&lt;li&gt;✅ Сніг Canvas&lt;/li&gt;&lt;li&gt;✅ Сезонний&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;New Year Decor PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Перевірте модуль на демо-сайті&lt;/h3&gt;&lt;p&gt;Перед купівлею можна відкрити тестову адмін-панель і подивитися інтерфейс та логіку роботи доступних модулів.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестова адмінка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логін:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт призначений для ознайомлення. Набір встановлених модулів і тестові дані можуть змінюватися.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='New Year Decor PRO додає на вітрину легке святкове оформлення: гірлянди та сніг на Canvas. Ефекти не зачіпають товари, кошик, ціни та SEO, а при вимкненні…' WHERE `product_id`=109 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;New Year Decor PRO&lt;/strong&gt; is a professional CodeCart PRO module for OpenCart 3.0.x and ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;New Year Decor PRO&lt;/strong&gt; adds light seasonal decoration to the storefront: garlands and Canvas snow.&lt;/p&gt;&lt;h3&gt;💡 Why you need it&lt;/h3&gt;&lt;p&gt;Effects never touch products, cart, prices or SEO, and when off the module loads no CSS, JS or HTML.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Interactive ornament garland and a classic string-light garland&lt;/li&gt;&lt;li&gt;✅ Five graphic garland variants built on one seamless local WebP tile&lt;/li&gt;&lt;li&gt;✅ Two “Celebration” variants without a tree — for birthdays and promotions all year&lt;/li&gt;&lt;li&gt;✅ Light Canvas snow, with a “custom WebP snowflake” mode using a transparent image&lt;/li&gt;&lt;li&gt;✅ Effects can run separately or together&lt;/li&gt;&lt;li&gt;✅ Changes nothing in products, checkout, images, image cache, SEO, prices, currencies or orders&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Install and activate the license&lt;/li&gt;&lt;li&gt;2️⃣ Pick the garland and snow&lt;/li&gt;&lt;li&gt;3️⃣ Enable the module for the holiday period&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Without an active license the status stays off.&lt;/li&gt;&lt;li&gt;✅ Turn the decoration off after the holidays.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;li&gt;✅ You can see the module in action in the demo admin before buying.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, including 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Garlands&lt;/li&gt;&lt;li&gt;✅ Canvas snow&lt;/li&gt;&lt;li&gt;✅ Seasonal&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;New Year Decor PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Try the module on the demo site&lt;/h3&gt;&lt;p&gt;Before buying you can open the test admin panel and look at the interface and logic of the available modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Demo admin:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Login:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Password:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;The demo site is for evaluation. The set of installed modules and test data may change.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='New Year Decor PRO adds light seasonal decoration to the storefront: garlands and Canvas snow. Effects never touch products, cart, prices or SEO, and when…' WHERE `product_id`=109 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;New Year Decor PRO&lt;/strong&gt; — профессиональный модуль CodeCart PRO для OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;New Year Decor PRO&lt;/strong&gt; добавляет на витрину лёгкое праздничное оформление: гирлянды и снег на Canvas.&lt;/p&gt;&lt;h3&gt;💡 Зачем нужен модуль&lt;/h3&gt;&lt;p&gt;Эффекты не затрагивают товары, корзину, цены и SEO, а при выключении модуль не подключает ни CSS, ни JS, ни HTML.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Интерактивная гирлянда с игрушками и классическая световая гирлянда&lt;/li&gt;&lt;li&gt;✅ Пять графических вариантов гирлянды на одном бесшовном локальном WebP-тайле&lt;/li&gt;&lt;li&gt;✅ Два варианта «Праздник» без ёлки — для дней рождения и акций в течение года&lt;/li&gt;&lt;li&gt;✅ Лёгкий снег на Canvas, режим «Своя WebP-снежинка» с прозрачным изображением&lt;/li&gt;&lt;li&gt;✅ Эффекты включаются отдельно или вместе&lt;/li&gt;&lt;li&gt;✅ Не меняет товары, оформление заказа, изображения, кеш, SEO, цены, валюты и заказы&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Установите и активируйте лицензию&lt;/li&gt;&lt;li&gt;2️⃣ Выберите гирлянду и снег&lt;/li&gt;&lt;li&gt;3️⃣ Включите модуль на период праздников&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Без активной лицензии статус остаётся выключенным.&lt;/li&gt;&lt;li&gt;✅ Отключайте оформление после праздников.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;li&gt;✅ Работу модуля можно посмотреть в демо-админке до покупки.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;✅ ocStore 3.0.x, включая 3.0.4.1&lt;/li&gt;&lt;li&gt;✅ Гирлянды&lt;/li&gt;&lt;li&gt;✅ Снег Canvas&lt;/li&gt;&lt;li&gt;✅ Сезонный&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;New Year Decor PRO&lt;/strong&gt; — решение CodeCart PRO для магазинов на OpenCart и ocStore. Подробности и тестовый доступ — в демо-админке ниже.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background:#eef7ff;border:1px solid #bfdbfe;border-radius:14px;padding:18px 20px;margin-top:24px;color:#0b1b3a&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#0b4fa5;&quot;&gt;🧪 Проверьте модуль на демо-сайте&lt;/h3&gt;&lt;p&gt;Перед покупкой можно открыть тестовую админ-панель и посмотреть интерфейс и логику работы доступных модулей.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Тестовая админка:&lt;/strong&gt; &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;👤 &lt;strong&gt;Логин:&lt;/strong&gt; Demo&lt;br&gt;🔑 &lt;strong&gt;Пароль:&lt;/strong&gt; Demo&lt;/p&gt;&lt;p style=&quot;margin-bottom:0;&quot;&gt;&lt;small&gt;Демо-сайт предназначен для ознакомления. Набор установленных модулей и тестовые данные могут меняться.&lt;/small&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Где приобрести модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модули CodeCart PRO можно приобрести на этом сайте. Дополнительный официальный канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профиль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатой проверьте актуальную версию, цену и условия конкретного предложения.&lt;/p&gt;&lt;/div&gt;', `meta_description`='New Year Decor PRO добавляет на витрину лёгкое праздничное оформление: гирлянды и снег на Canvas. Эффекты не затрагивают товары, корзину, цены и SEO, а при…' WHERE `product_id`=109 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Module Preflight PRO&lt;/strong&gt; — професійна Windows-утиліта CodeCart PRO для перевірки модулів OpenCart 3.0.x та ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Module Preflight PRO&lt;/strong&gt; — portable-програма для Windows, яка перевіряє ZIP-архів модуля OpenCart/ocStore до встановлення на сайт.&lt;/p&gt;&lt;h3&gt;💡 Навіщо потрібен модуль&lt;/h3&gt;&lt;p&gt;Код, що перевіряється, не виконується, а вихідний архів не змінюється.&lt;/p&gt;&lt;h3&gt;💎 Основні можливості&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Read-only перевірка ZIP: код модуля не запускається&lt;/li&gt;&lt;li&gt;✅ SHA-256 архіву порівнюється до й після перевірки&lt;/li&gt;&lt;li&gt;✅ Статичний аудит безпеки: небезпечні виклики, web-shell-патерни, tainted-потоки, remote include, руйнівні операції&lt;/li&gt;&lt;li&gt;✅ Динамічні SQL-ідентифікатори оцінюються за taint/whitelist, а не вважаються помилкою автоматично&lt;/li&gt;&lt;li&gt;✅ Portable PHP lint для PHP 7.4 і 8.1–8.5&lt;/li&gt;&lt;li&gt;✅ Статус стороннього антивіруса Windows показується інформаційно&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Як це працює&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Запустіть програму без встановлення&lt;/li&gt;&lt;li&gt;2️⃣ Перетягніть ZIP/.ocmod.zip модуля&lt;/li&gt;&lt;li&gt;3️⃣ Вивчіть звіт і вирішіть, чи ставити модуль&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важливо знати&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Це статичний аналіз: він знижує ризик, але не замінює резервну копію та перевірку на тестовій копії.&lt;/li&gt;&lt;li&gt;✅ Перед встановленням і оновленням зробіть резервну копію файлів сайту та бази даних.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Сумісність і технології&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Windows portable&lt;/li&gt;&lt;li&gt;✅ Статичний аудит&lt;/li&gt;&lt;li&gt;✅ PHP lint&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Підсумок&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Module Preflight PRO&lt;/strong&gt; — рішення CodeCart PRO для магазинів на OpenCart та ocStore. Подробиці й тестовий доступ — у демо-адмінці нижче.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Де придбати модуль&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;Модулі CodeCart PRO можна придбати на цьому сайті. Додатковий офіційний канал — &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;профіль CodeCart PRO на OpenCartForum&lt;/a&gt;. Перед оплатою перевірте актуальну версію, ціну та умови конкретної пропозиції.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Module Preflight PRO — portable-програма для Windows, яка перевіряє ZIP-архів модуля OpenCart/ocStore до встановлення на сайт. Код, що перевіряється, не…' WHERE `product_id`=110 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Module Preflight PRO&lt;/strong&gt; is a professional CodeCart PRO Windows utility for vetting OpenCart 3.0.x and ocStore 3.0.x modules.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Module Preflight PRO&lt;/strong&gt; is a portable Windows utility that checks an OpenCart/ocStore module ZIP before it is installed on a site.&lt;/p&gt;&lt;h3&gt;💡 Why you need it&lt;/h3&gt;&lt;p&gt;The inspected code is never executed and the source archive is not modified.&lt;/p&gt;&lt;h3&gt;💎 Key features&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Read-only ZIP check: module code is not run&lt;/li&gt;&lt;li&gt;✅ The archive SHA-256 is compared before and after the check&lt;/li&gt;&lt;li&gt;✅ Static security audit: dangerous calls, web-shell patterns, tainted flows, remote include, destructive operations&lt;/li&gt;&lt;li&gt;✅ Dynamic SQL identifiers are judged by taint/whitelist, not flagged just for being dynamic&lt;/li&gt;&lt;li&gt;✅ Portable PHP lint for PHP 7.4 and 8.1–8.5&lt;/li&gt;&lt;li&gt;✅ Third-party antivirus status from Windows Security Center is shown for information only&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 How it works&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Run the program, no installation needed&lt;/li&gt;&lt;li&gt;2️⃣ Drop the module ZIP/.ocmod.zip&lt;/li&gt;&lt;li&gt;3️⃣ Read the report and decide whether to install&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Good to know&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ This is static analysis: it lowers risk but does not replace a backup and a test on a staging copy.&lt;/li&gt;&lt;li&gt;✅ Back up your site files and database before installing or updating.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Compatibility and technology&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Windows portable&lt;/li&gt;&lt;li&gt;✅ Static audit&lt;/li&gt;&lt;li&gt;✅ PHP lint&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Summary&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Module Preflight PRO&lt;/strong&gt; is a CodeCart PRO solution for OpenCart and ocStore stores. Details and test access are in the demo admin below.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;ccp-buy-channels&quot; style=&quot;background:#fff8e6;border:1px solid #eed493;border-radius:14px;padding:20px 22px;margin:22px 0;color:#3d2e00&quot;&gt;&lt;h3 style=&quot;margin:0 0 10px;color:#8b6100;&quot;&gt;🛒 Where to buy&lt;/h3&gt;&lt;p style=&quot;margin:0;&quot;&gt;CodeCart PRO modules can be purchased on this site. An additional official channel is the &lt;a href=&quot;https://opencartforum.com/files/developer/1123944-codecartpro/?utm_source=opencartforum&amp;amp;utm_medium=profilecpage&amp;amp;utm_campaign=profile&quot; rel=&quot;noopener&quot;&gt;CodeCart PRO profile on OpenCartForum&lt;/a&gt;. Check the current version, price and terms of the specific offer before paying.&lt;/p&gt;&lt;/div&gt;', `meta_description`='Module Preflight PRO is a portable Windows utility that checks an OpenCart/ocStore module ZIP before it is installed on a site. The inspected code is never…' WHERE `product_id`=110 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;codecart-product-description&quot;&gt;&lt;p&gt;🚀 &lt;strong&gt;Module Preflight PRO&lt;/strong&gt; — профессиональная Windows-утилита CodeCart PRO для проверки модулей OpenCart 3.0.x и ocStore 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Module Preflight PRO&lt;/strong&gt; — portable-программа для Windows, которая проверяет ZIP-архив модуля OpenCart/ocStore до установки на сайт.&lt;/p&gt;&lt;h3&gt;💡 Зачем нужен модуль&lt;/h3&gt;&lt;p&gt;Проверяемый код не выполняется, а исходный архив не изменяется.&lt;/p&gt;&lt;h3&gt;💎 Основные возможности&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Read-only проверка ZIP: код модуля не запускается&lt;/li&gt;&lt;li&gt;✅ SHA-256 архива сравнивается до и после проверки&lt;/li&gt;&lt;li&gt;✅ Статический аудит безопасности: опасные вызовы, web-shell-паттерны, tainted-потоки, remote include, разрушительные операции&lt;/li&gt;&lt;li&gt;✅ Динамические SQL-идентификаторы оцениваются по taint/whitelist, а не считаются ошибкой автоматически&lt;/li&gt;&lt;li&gt;✅ Portable PHP lint для PHP 7.4 и 8.1–8.5&lt;/li&gt;&lt;li&gt;✅ Статус сторонего антивируса Windows показывается информационно&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🧭 Как это работает&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;1️⃣ Запустите программу без установки&lt;/li&gt;&lt;li&gt;2️⃣ Перетащите ZIP/.ocmod.zip модуля&lt;/li&gt;&lt;li&gt;3️⃣ Изучите отчёт и решите, ставить ли модуль&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🔐 Важно знать&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Это статический анализ: он снижает риск, но не заменяет резервную копию и проверку на тестовой копии.&lt;/li&gt;&lt;li&gt;✅ Перед установкой и обновлением сделайте резервную копию файлов сайта и базы данных.&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;⚙️ Совместимость и технологии&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;✅ Windows portable&lt;/li&gt;&lt;li&gt;✅ Статический аудит&lt;/li&gt;&lt;li&gt;✅ PHP lint&lt;/li&gt;&lt;/ul&gt;&lt;h3&gt;🏆 Итог&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Module Preflight PRO&lt;/strong&gt; — реше